window.QA_V3 = [{"module": 6, "kind": "slide", "slides": [2], "q": "What is memory?", "a": "Memory includes retaining, retrieving and using information about stimuli, images, events, ideas and skills after the original information is no longer present. A past experience can influence current or future behavior without being visible in the environment.", "id": 0, "score": 2.075, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [2], "q": "How did Endel Tulving describe episodic memory?", "a": "Endel Tulving described episodic memory as a kind of mental time travel, because remembering an event connects it back to the experienced past.", "id": 1, "score": 1.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [3], "q": "What are encoding, storage and retrieval?", "a": "Encoding converts information into a usable form for storage, storage retains it, and retrieval makes it available again.", "id": 2, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [3], "q": "Is memory an unchanged copy of an experience?", "a": "No. Memory is an active system that can organize and alter information rather than retaining an unchanged copy in every case.", "id": 3, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [3], "q": "Why does a failure to use information not tell you which memory operation went wrong?", "a": "A failure to use information could reflect a problem at more than one of the operations, encoding, storage or retrieval, so the failure alone does not identify which one failed.", "id": 4, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [4], "q": "What kinds of memory does the memory tree distinguish?", "a": "The memory tree distinguishes sensory memory, short-term memory and long-term memory.", "id": 5, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [4], "q": "What are declarative memory and procedural memory?", "a": "Long-term memory includes declarative memory, which contains episodic events and semantic knowledge, and procedural memory, which concerns skills.", "id": 6, "score": 4.7, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [4], "q": "Where do episodic and semantic memory sit in the memory tree?", "a": "They are branches of declarative memory, which is part of long-term memory. They are not additional short-term stores.", "id": 7, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [5], "q": "What are the three stores of Atkinson and Shiffrin’s (1968) modal model?", "a": "Sensory memory, short-term memory and long-term memory.", "id": 8, "note": "The slides give short-term memory as five to seven items for about fifteen to twenty seconds. Modern work puts working capacity nearer three to four chunks, which matches the three to four items the slides give for visual short-term memory.", "score": 9.2, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [5], "q": "How long does each store in the modal model hold information, and how much?", "a": "Sensory memory briefly retains incoming stimulation for seconds or fractions of a second. Short-term memory holds five to seven items for about 15 to 20 seconds. Long-term memory retains large amounts for years or decades.", "id": 9, "score": 7.5, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [5], "q": "What is rehearsal in the modal model?", "a": "Rehearsal is a control process that can keep information available and support transfer.", "id": 10, "score": 8.2, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [6], "q": "What happens to the information when you look at a phone directory?", "a": "The many pieces of visual information enter sensory memory first, and the store briefly preserves them so attention can select relevant material. Not every detail is retained indefinitely.", "id": 11, "score": 0.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [6], "q": "Are sensory registration and durable learning the same outcome?", "a": "No. They are different outcomes, because something can be registered briefly in sensory memory without being learned.", "id": 12, "score": 0.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [7], "q": "What does attention do between sensory memory and short-term memory?", "a": "Focusing on a particular phone number transfers that information into short-term memory. Selection limits which part of the large sensory input receives further processing.", "id": 13, "score": 1.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [8], "q": "What is maintenance rehearsal, and what does it do for a phone number?", "a": "Maintenance rehearsal repeats the information, so repeating the number keeps it available in short-term memory long enough to make a call. It prolongs access that would otherwise be vulnerable to loss or interference.", "id": 14, "score": 1.75, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [9], "q": "How can a rehearsed phone number end up in long-term memory?", "a": "A rehearsed number can become represented in long-term memory, so later use no longer depends on the directory still being visible.", "id": 15, "score": 0.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [10], "q": "What happens when a stored number is later retrieved?", "a": "It is retrieved from long-term memory into short-term memory for dialing. Remembering requires bringing stored information back into an active form, so the movement is not only one way toward long-term storage.", "id": 16, "score": 1.75, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [11], "q": "What are an icon and an echo?", "a": "An icon is a fleeting visual representation, and an echo is a brief continuation of auditory information after a sound. The two differ in modality, and neither is a durable representation used to remember something much later.", "id": 17, "score": 5.075, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [12], "q": "What is persistence of vision?", "a": "Persistence of vision is the brief retention of the perception of light, which contributes to a sparkler’s trail and to the continuity experienced from film frames.", "id": 18, "note": "Film continuity is usually attributed to apparent motion (the phi phenomenon) and flicker fusion, not persistence of vision. Persistence of vision does account for the sparkler trail.", "score": 0.7, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [12], "q": "Does the large capacity of sensory memory mean it lasts a long time?", "a": "No. Sensory memory holds much information for a short interval, but its large capacity does not imply long duration, because the information decays quickly.", "id": 19, "score": 0.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [13], "q": "What did Sperling (1960) do, and what question did it address?", "a": "Sperling (1960) flashed an array of letters and asked participants to report what they had seen. The question was whether limited report reflects limited initial registration or rapid loss before all letters could be reported.", "id": 20, "score": 6.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [14], "q": "What are whole report, partial report and delayed partial report in Sperling (1960)?", "a": "In Sperling (1960), whole report had participants report as many letters as possible, partial report used a tone after the display to identify which row to recall, and in delayed partial report the tone occurred after an additional delay.", "id": 21, "score": 2.125, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [14], "q": "Why does strong immediate partial report in Sperling (1960) show that several rows were available at first?", "a": "In Sperling (1960), the row is not identified until after viewing, so accurate report of whichever row is cued implies that information about multiple rows was initially available.", "id": 22, "score": 2.125, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [15], "q": "What was in Sperling’s (1960) array, and what did the cue do?", "a": "The array was X M L T, A F N B and C D Z P. A cue after the array selects a row for report rather than telling the observer in advance which row to memorize, and increasing cue delay lets the sensory trace fade.", "id": 23, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [15], "q": "What does Sperling’s (1960) procedure separate?", "a": "It separates initial availability from the ability to report every item before it disappears.", "id": 24, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [16], "q": "What were Sperling’s (1960) results for whole, immediate partial and delayed partial report?", "a": "Whole report averaged 4.5 of 12 letters, 37.5 percent. Immediate partial report averaged 3.3 of 4 letters, about 82 percent, whichever row was selected. Delayed partial report averaged 1 of 4, or 25 percent.", "id": 25, "score": 8.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [17], "q": "Does the whole-report limit of four to five letters in Sperling (1960) show that only that many were perceived?", "a": "No. In Sperling (1960), immediate partial report permits accurate report of whichever row is cued, so report limitations can conceal greater initial availability.", "id": 26, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [17], "q": "What do Sperling’s (1960) results say about the capacity and duration of sensory memory?", "a": "Sensory memory has large capacity but rapid decay, with most information lost within about one second unless it is selected for further processing.", "id": 27, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [18], "q": "What happens to partial-report accuracy as the cue is delayed in Sperling (1960)?", "a": "In Sperling (1960), it decreases and approaches whole-report performance. The display is unchanged and only the interval before selection varies, which links the partial-report advantage to a rapidly fading representation. It does not support indefinite retention of the whole array.", "id": 28, "score": 7.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [19], "q": "What is short-term memory, and what is memory span?", "a": "Short-term memory retains small amounts briefly and is sensitive to interruption and interference. Memory span is the amount that can be recalled accurately in a task.", "id": 29, "score": 0.375, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [19], "q": "What is the traditional estimate of memory span?", "a": "Seven plus or minus two units. It depends on the kind of units and the task, and should not be used for every visual-memory capacity result.", "id": 30, "note": "Miller’s seven plus or minus two is about chunks, and modern estimates are nearer four chunks. The slides also give five to seven items elsewhere, so the two figures on the slides do not match each other.", "score": 1.075, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [20], "q": "What is recoding?", "a": "Recoding reorganizes or modifies information in short-term memory.", "id": 31, "score": 5.075, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [20], "q": "How do maintenance rehearsal and elaborative rehearsal differ?", "a": "Maintenance rehearsal repeats information to prolong its availability. Elaborative rehearsal links new information with existing long-term knowledge, which supports longer-term learning.", "id": 32, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [21], "q": "What is short-term memory’s role in current thought?", "a": "It includes selected sensory input and information retrieved from long-term memory, and it is needed to understand sentences, do arithmetic, dial a number and navigate. It acts as a window on the present.", "id": 33, "score": 0.7, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [22], "q": "What does the case of Clive Wearing show?", "a": "Clive Wearing is a case of memory impairment. Keeping immediate information and remembering across events are different memory functions, so a case like his has to be analyzed function by function.", "id": 34, "score": 0.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [23], "q": "How do duration and capacity differ in memory?", "a": "Duration is how long information remains available, and capacity is how much can be held.", "id": 35, "score": 5.125, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [23], "q": "How do rehearsal and chunking affect the measurement of memory stores?", "a": "Rehearsal can extend duration and chunking can extend effective capacity, so a result can reflect the strategy used as well as the memory system being studied.", "id": 36, "score": 5.125, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [24], "q": "What was the Brown–Peterson procedure of Brown (1958) and Peterson and Peterson (1959)?", "a": "Participants were shown three letters followed by a number, counted backward by threes during a delay of 3 to 18 seconds, and then recalled the letters.", "id": 37, "note": "Brown and Peterson and Peterson found the decline in recall with delay. The trial-by-trial proactive-interference analysis is usually credited to Keppel and Underwood (1962), who are not named on these slides.", "score": 9.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [24], "q": "Why did Brown (1958) and Peterson and Peterson (1959) have participants count backward by threes?", "a": "Counting prevents ordinary maintenance rehearsal, so comparing delays measures retention when participants cannot simply keep repeating the letters.", "id": 38, "score": 9.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [25], "q": "What happened to recall on the first trial in Brown (1958) and Peterson and Peterson (1959)?", "a": "Recall was high at three seconds and stayed relatively high at eighteen seconds, because no earlier trigrams from the task competed with the current one.", "id": 39, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [26], "q": "What happened to recall on the third trial in Brown (1958) and Peterson and Peterson (1959)?", "a": "Recall at eighteen seconds was lower than on the first trial, because earlier trigrams now provided competing information. The same delay can have different effects depending on the preceding trials.", "id": 40, "score": 4.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [27], "q": "What happened to recall after many trials in Brown (1958) and Peterson and Peterson (1959)?", "a": "Recall at longer delays was substantially reduced, because accumulated earlier material can interfere with the currently tested trigram.", "id": 41, "score": 3.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [28], "q": "Why does the average over all trials give a misleading impression in Brown (1958) and Peterson and Peterson (1959)?", "a": "The average shows a decline from shorter to longer delays, but it combines early trials with little interference and later trials with more. It can hide important differences by trial position, so the overall curve can hide important differences by trial position.", "id": 42, "note": "The slides say recall at 18 seconds is relatively high on the first trial and substantially reduced on later trials, and that the average combines early trials with little interference and later trials with more. The words steady and very low are stronger than the slides.", "score": 3.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [29], "q": "How do delay and trial history combine in Brown (1958) and Peterson and Peterson (1959)?", "a": "Percent recalled decreases with longer delays, but the pattern interacts with where a trial occurs in the sequence. Long-delay performance worsens as more trials are completed, so delay and accumulated interference jointly affect retention.", "id": 43, "score": 7.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [30], "q": "What are decay and proactive interference?", "a": "Decay is loss associated with the passage of time. Proactive interference occurs when earlier information disrupts remembering newer information.", "id": 44, "score": 7.825, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [30], "q": "What is the effective duration of short-term memory, and what affects it?", "a": "About 15 to 20 seconds, with rehearsal and interference conditions affecting the observed outcome.", "id": 45, "score": 7.125, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [31], "q": "What is interference, and how do the two kinds differ?", "a": "Interference occurs when memories compete with or replace one another, so forgetting is not explained solely by elapsed time. Retroactive and proactive interference differ in the direction of the competition.", "id": 46, "score": 2.125, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [32], "q": "What is retroactive interference?", "a": "Retroactive interference occurs when new information disrupts memory for older information. Learning a new phone number making the old one harder to retrieve is an example.", "id": 47, "score": 5.075, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [33], "q": "What is proactive interference?", "a": "Proactive interference occurs when old information disrupts memory for newer information. Previous parking locations interfering with remembering where you parked today is an example.", "id": 48, "score": 5.075, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [33], "q": "What can reduce both kinds of interference?", "a": "Both can be reduced when events are distinctive.", "id": 49, "score": 4.375, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [34], "q": "What is digit span?", "a": "Digit span measures the longest sequence of digits recalled correctly in order. Capacity differs between individuals and can be affected by strategies.", "id": 50, "score": 5.075, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [35], "q": "How is digit span scored?", "a": "The longest row reproduced completely and in order defines the span. One successful short list does not establish the limit, and one missed digit makes a longer list incorrect.", "id": 51, "score": 0.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [36], "q": "What did Miller (1956) propose?", "a": "Miller (1956), in The Magical Number Seven, Plus or Minus Two, proposed an influential capacity description in which the units remembered can differ across tasks.", "id": 52, "score": 5.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [37], "q": "Does Miller’s (1956) number mean every short-term system stores exactly seven raw items?", "a": "No. The units can be digits, words, numbers or phrases, and a unit can contain different amounts of information.", "id": 53, "score": 9.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [37], "q": "What did Alvarez and Cavanagh (2004) compare?", "a": "They compared colored squares with more complex objects using change detection. The emphasis is on the amount or complexity of information, not a fixed number of equally sized items.", "id": 54, "score": 9.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [38], "q": "What is visual short-term memory, and how is it measured?", "a": "Visual short-term memory, VSTM, is measured by comparing displays after a delay. Its capacity can be smaller than span for digit lists or unrelated words.", "id": 55, "score": 1.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [39], "q": "What happens in the first display, S1, of a change-detection task?", "a": "Participants view an initial array briefly, 100 milliseconds, and must retain relevant visual properties after it disappears.", "id": 56, "score": 2.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [40], "q": "What must a short-term visual representation preserve?", "a": "The features needed for comparison. Color, shape, orientation and complexity can affect how demanding that retention is.", "id": 57, "score": 0.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [41], "q": "What happens in the second display, S2, of a change-detection task?", "a": "S2 appears for 2,000 milliseconds, and participants judge whether it is the same or different. Correct performance requires comparing S2 with the retained S1.", "id": 58, "score": 3.0, "tier": "mid"}, {"module": 6, "kind": "slide", "slides": [42], "q": "What does set size do to change-detection accuracy?", "a": "Accuracy falls sharply when set size exceeds roughly four items, giving a capacity of about three to four items in visual working memory.", "id": 59, "score": 6.375, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [43], "q": "How does stimulus complexity affect visual capacity?", "a": "Colored squares support a higher estimated capacity than more complex polygons or shaded cubes. Treating all stimuli as equally sized items hides these differences.", "id": 60, "score": 6.375, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [44], "q": "Why is a capacity estimate for one stimulus category not universal?", "a": "Familiarity and the structure attributed to a stimulus can affect what counts as a unit of information, so differences must be interpreted relative to the stimulus classes used. Chinese-character-like forms were also compared.", "id": 61, "score": 2.0, "tier": "low"}, {"module": 6, "kind": "slide", "slides": [45], "q": "What is chunking, and what did Ericsson and colleagues (1980) show?", "a": "Chunking combines smaller units into larger meaningful units. Ericsson and colleagues (1980) trained a student to reach a digit span of 79 by using familiar running times to organize sequences.", "id": 62, "score": 9.375, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [45], "q": "What did Chase and Simon (1973) find?", "a": "Chess expertise supports grouping meaningful positions. The gain depends on knowledge-based organization and not on expanding every raw memory limit equally.", "id": 63, "score": 9.375, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [46], "q": "How do chess masters differ from beginners in recalling piece placements in Chase and Simon (1973)?", "a": "In Chase and Simon (1973), masters recall more correct placements for meaningful game arrangements, but the advantage is greatly reduced for random arrangements.", "id": 64, "score": 7.0, "tier": "high"}, {"module": 6, "kind": "slide", "slides": [47], "q": "What are control processes, and what does the memory palace show?", "a": "Control processes include rehearsal, strategies for making material memorable and directing attention. The memory palace organizes information through a remembered spatial structure. These active operations lead toward working memory, which concerns using and managing currently available information.", "id": 65, "score": 1.75, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [5, 7, 8, 9, 10], "q": "How do attention and rehearsal connect the three stores of the modal model?", "a": "Attention selects part of the large sensory input for short-term memory, and rehearsal keeps that information available and can support its transfer to long-term memory. Retrieval then brings long-term information back into short-term memory.", "id": 66, "score": 6.02, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [5, 17, 19], "q": "How does sensory memory differ from short-term memory in capacity and duration?", "a": "Sensory memory has large capacity but decays within about one second unless selected, while short-term memory holds only a small amount, five to seven items, for about 15 to 20 seconds.", "id": 67, "score": 6.45, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [14, 16, 17], "q": "Why does Sperling’s (1960) result show that the whole-report limit is a report limit?", "a": "Immediate partial report was about 82 percent for whichever row was cued, so far more was available than the four to five letters reported in whole report. The limit came from rapid decay before everything could be reported.", "id": 68, "score": 7.183, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [18, 24], "q": "How are Sperling’s (1960) delay manipulation and the Brown–Peterson delay similar, and what do they test?", "a": "Both vary the time before report. Sperling’s delayed cue shows a fading sensory trace, while Brown (1958) and Peterson and Peterson (1959) vary the delay in short-term memory while blocking rehearsal.", "id": 69, "score": 9.1, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [29, 30, 31], "q": "How do decay and interference differ as explanations of forgetting?", "a": "Decay is loss from the passage of time, while interference is memories competing or replacing one another. The Brown–Peterson trial pattern is evidence that forgetting is not explained solely by elapsed time.", "id": 70, "score": 6.808, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [27, 30, 32, 33], "q": "Which kind of interference does the Brown–Peterson pattern show, and how does it differ from retroactive interference?", "a": "It shows proactive interference, where earlier trigrams disrupt the new one. Retroactive interference runs the other way, with new information disrupting older memories.", "id": 71, "score": 6.6, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [8, 20], "q": "How do maintenance rehearsal and elaborative rehearsal differ in what they accomplish?", "a": "Maintenance rehearsal prolongs availability in short-term memory, while elaborative rehearsal links information with long-term knowledge and supports longer-term learning.", "id": 72, "score": 4.35, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [23, 45], "q": "How do duration, capacity and strategy interact when stores are measured?", "a": "Rehearsal can extend duration and chunking can extend effective capacity, so a measurement can reflect the strategy as well as the store.", "id": 73, "score": 8.225, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [5, 19, 36, 42, 43], "q": "Why is there no single capacity number for short-term memory?", "a": "Estimates include five to seven items, seven plus or minus two units, and about three to four items for visual short-term memory. The estimate depends on the kind of units, the task and the stimulus complexity.", "id": 74, "score": 6.97, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [34, 35, 39, 41], "q": "How do digit span and change detection measure capacity differently?", "a": "Digit span measures the longest list recalled correctly in order, while change detection compares a second display with a retained first display after a delay.", "id": 75, "score": 4.062, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [36, 37, 43], "q": "How do Miller (1956) and Alvarez and Cavanagh (2004) differ on what capacity is counted in?", "a": "Miller (1956) counts units such as digits or words, while Alvarez and Cavanagh (2004) emphasize the amount or complexity of information in each item.", "id": 76, "score": 8.75, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [45, 46], "q": "How does chunking explain the chess results of Chase and Simon (1973)?", "a": "Masters group pieces into meaningful chunks of familiar relationships. Random arrangements remove those relationships, so the advantage mostly disappears.", "id": 77, "score": 9.4, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [45, 46], "q": "How do Ericsson and colleagues (1980) and Chase and Simon (1973) show the same principle?", "a": "Both show that knowledge-based organization extends effective capacity. The student used familiar running times to organize digits, and chess masters used familiar piece relationships, without expanding every raw memory limit equally.", "id": 78, "score": 9.4, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [3, 5, 10], "q": "How do encoding, storage and retrieval relate to the three stores?", "a": "Encoding, storage and retrieval are operations on information, while sensory, short-term and long-term memory are the stores. Information is encoded for storage, retained in a store, and retrieved back into an active form, as when a phone number returns from long-term to short-term memory.", "id": 79, "score": 6.817, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [4, 5], "q": "How do the memory tree and the modal model each organize memory, and where do they overlap?", "a": "The memory tree distinguishes sensory, short-term and long-term memory, with long-term memory including declarative and procedural memory. The modal model distinguishes the same three stores and adds rehearsal as a control process. Both treat sensory, short-term and long-term memory as distinct.", "id": 80, "score": 7.3, "tier": "mid"}, {"module": 6, "kind": "relate", "slides": [11, 12], "q": "How is the icon related to persistence of vision and sensory memory?", "a": "An icon is a fleeting visual representation in sensory memory, and persistence of vision is the brief retention of the perception of light that contributes to a sparkler’s trail and to the continuity experienced from film frames. Both are brief and neither is a durable representation.", "id": 81, "score": 4.0, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [21, 22, 23], "q": "Why must different memory functions be distinguished when studying a case like Clive Wearing?", "a": "Keeping immediate information and remembering across events are different functions, so analyzing the case function by function avoids assuming one memory system explains everything.", "id": 82, "score": 4.258, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [10, 21], "q": "How does short-term memory as a window on the present depend on long-term memory?", "a": "Short-term memory includes information retrieved from long-term memory as well as selected sensory input, so current thought draws on both.", "id": 83, "score": 1.9, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [20, 47], "q": "How do control processes lead into working memory?", "a": "Rehearsal, memorability strategies and directing attention are active operations on available information, which is what working memory concerns, using and managing information that is currently available.", "id": 84, "score": 4.35, "tier": "low"}, {"module": 6, "kind": "relate", "slides": [23, 24, 45], "q": "How do the Brown–Peterson counting task and chunking each relate to strategy in memory measurement?", "a": "Counting backward by threes prevents ordinary maintenance rehearsal, so retention is measured without simple repetition. Chunking extends effective capacity, so results must account for control processes such as rehearsal and chunking.", "id": 85, "score": 8.392, "tier": "high"}, {"module": 6, "kind": "relate", "slides": [17, 37, 42, 43], "q": "How do the tasks of Sperling (1960) and Alvarez and Cavanagh (2004) each show that a capacity estimate depends on how it is measured?", "a": "In Sperling (1960), the whole-report limit hid the larger initial availability, and in change detection the capacity estimate depends on stimulus type, delay and the response required.", "id": 86, "score": 8.675, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [2], "q": "Why is treating short-term memory as passive storage too simple?", "a": "Keeping information available also involves control processes, which are operations that act on that information. A memory model has to account for both holding something in mind and doing something with it.", "id": 87, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [2], "q": "What is working memory according to Baddeley and Hitch (1974)?", "a": "Working memory is a limited-capacity system for the temporary storage and manipulation of information. Storage keeps information available for immediate use, and manipulation changes or works with it while it remains available.", "id": 88, "score": 8.45, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [2], "q": "Why do comprehension, learning and reasoning need working memory?", "a": "They can require storage and manipulation together. Comprehension keeps information available while relating its parts, and reasoning maintains the information used in a decision while performing the operations that lead to an answer.", "id": 89, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [2], "q": "What does manipulation mean in Baddeley and Hitch’s (1974) definition of working memory?", "a": "Manipulation changes or works with information while it remains available, as opposed to storage, which keeps information available for immediate use.", "id": 90, "score": 7.75, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [3], "q": "How does mentally multiplying 43 times 6 use both storage and processing?", "a": "First 3 × 6 = 18. The 8 is held as the ones digit, which is storage, and the 1 is carried over the 4, which is an operation. Then 6 × 4 = 24, plus the carried 1 gives 25, and combining it with the held 8 gives 258.", "id": 91, "score": 1.375, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [3], "q": "What does working memory account for in the 43 × 6 calculation?", "a": "It accounts for keeping an intermediate result available while changing other parts of the problem, and for coordinating which number is stored, which is carried and which operation is performed.", "id": 92, "score": 1.375, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [4], "q": "How does Atkinson and Shiffrin’s (1968) short-term memory model differ from Baddeley and Hitch’s (1974) working-memory model?", "a": "In Atkinson and Shiffrin’s model a single component holds different types of information for a short time. Baddeley and Hitch’s model separates the system into the central executive, the visuospatial sketchpad and the phonological loop.", "id": 93, "score": 6.5, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [4], "q": "What is the episodic buffer in relation to the original working-memory model?", "a": "It is a fourth component added by Baddeley in 2000. It belongs to the expanded model and not to the original three-component proposal.", "id": 94, "score": 5.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [5], "q": "What does the phonological loop do, and what are its two parts?", "a": "It maintains verbal and auditory information. Its phonological store holds that information, and its articulatory rehearsal process keeps it active through rehearsal.", "id": 95, "score": 5.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [5], "q": "What does articulatory mean, and how does articulatory rehearsal work?", "a": "Articulatory refers to producing speech. Rehearsal can involve repeating the sounds internally rather than aloud, which refreshes information that would otherwise decay in the store.", "id": 96, "score": 5.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [5], "q": "What does the visuospatial sketchpad hold?", "a": "Visual and spatial information. Visual information concerns the appearance of something, and spatial information concerns where its parts are located and how they are arranged.", "id": 97, "score": 5.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [5], "q": "What does the central executive do?", "a": "It pulls information from long-term memory, coordinates the other components, and directs and maintains attention. It controls how the temporary stores contribute to the task and is not a store for a particular kind of information.", "id": 98, "score": 5.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [6], "q": "How do the working-memory components interact with each other and with long-term knowledge?", "a": "They form interacting parts rather than a single store, so a task can use more than one kind of representation, such as verbal rehearsal of a result with a visual picture of the digits. Long-term knowledge is connected to the components and can be made available during a task.", "id": 99, "score": 2.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [6], "q": "How can a calculation use both verbal and visual representations?", "a": "The connections between components allow a task to use more than one kind of representation, such as verbal rehearsal of a result together with a visual representation of the digits.", "id": 100, "score": 2.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [7], "q": "What is the phonological similarity effect?", "a": "It occurs when letters or words that sound similar are confused. Items are hard to keep distinct when their sound patterns overlap, even if their written forms differ.", "id": 101, "score": 3.2, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [7], "q": "What is the word-length effect?", "a": "Memory for lists is better for short words than for long words, because longer words take more time to rehearse and to produce during recall.", "id": 102, "score": 3.2, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [7], "q": "What is articulatory suppression?", "a": "It involves speaking while trying to remember other material. Speaking occupies the rehearsal process, so it interferes with the repetition that keeps verbal items available.", "id": 103, "score": 3.2, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [7], "q": "How do the three phonological loop effects concern different aspects of verbal maintenance?", "a": "Similarity concerns confusion between sound patterns, word length concerns the time required to repeat items, and suppression concerns interference with the rehearsal process itself.", "id": 104, "score": 2.5, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [8], "q": "What did Conrad (1964) do?", "a": "Conrad (1964) briefly flashed target letters, similar in half of the presentations and dissimilar in half, and asked participants to write them down.", "id": 105, "score": 9.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [8], "q": "What kind of errors did Conrad’s (1964) participants make?", "a": "They more often substituted a letter that sounded like the target than one that looked like it. An E was likely to be replaced by a B, while a visually similar substitution such as F for E was less likely.", "id": 106, "score": 9.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [9], "q": "What does Conrad’s (1964) result show about how seen letters are remembered?", "a": "Visually presented letters can be recoded into a sound-based representation through the phonological loop, so the confusions follow the pronunciation and not the appearance.", "id": 107, "score": 4.75, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [9], "q": "What is the difference between presentation format and memory code?", "a": "Presentation format is what participants see, while the memory code is the form in which the information is maintained. Letters seen visually can be maintained as sounds.", "id": 108, "score": 4.45, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [10], "q": "What did Baddeley and colleagues (1975, 1984) find about word length?", "a": "People remembered more short words than long words, because the word-length effect concerns how long items take to pronounce and rehearse.", "id": 109, "score": 9.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [10], "q": "What did Ellis and Hennelly (1980) find?", "a": "Welsh–English bilingual children had a shorter digit span in Welsh than in English, because Welsh number names take longer to pronounce, even though the children knew both languages.", "id": 110, "score": 9.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [10], "q": "How is memory span related to speaking time?", "a": "Span is related to the amount of verbal material that can be said in about 1.5 to 2 seconds, so faster rehearsal lets more items be refreshed.", "id": 111, "score": 8.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [11], "q": "What does articulatory suppression do to memory?", "a": "The competing speech keeps the phonological loop busy, so the person has less opportunity to rehearse and recall becomes worse.", "id": 112, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [11], "q": "What happens to the word-length effect under articulatory suppression?", "a": "It is reduced. Short words normally win because they can be rehearsed more quickly, and when rehearsal is occupied neither list gets ordinary rehearsal.", "id": 113, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [11], "q": "What happens to the phonological similarity effect under articulatory suppression?", "a": "It is also reduced, because verbal rehearsal and the conversion of seen items into sounds are disrupted, so sound overlap has less influence.", "id": 114, "note": "The similarity effect is abolished by articulatory suppression only when items are presented visually. With auditory presentation it persists.", "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [12], "q": "What is the difference between visual and spatial information in the sketchpad?", "a": "Visual information includes the appearance and shape of something, and spatial information includes the arrangement and relative locations of its parts, which allows that arrangement to remain available without continuous visual input.", "id": 115, "score": 2.125, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [12], "q": "What does the visuospatial sketchpad support?", "a": "Mental imagery, meaning keeping a visual representation in mind so it can be used during a task when it is no longer being viewed. Holding a shape in mind is a different demand from holding the sounds of a sentence.", "id": 116, "score": 2.125, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [13], "q": "What was the sentence task in Brooks (1968)?", "a": "Participants memorized a sentence and decided for each word whether it was a noun, responding either by speaking or by pointing.", "id": 117, "score": 10.5, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [13], "q": "What did Brooks (1968) find in the sentence task, and why?", "a": "Pointing was easier than speaking, because maintaining the sentence occupied the phonological loop and speaking the answers required verbal processing that competed with it.", "id": 118, "score": 10.5, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [14], "q": "What was the F task in Brooks (1968)?", "a": "Participants memorized the shape of an F, mentally followed its outline and classified each corner as an inside or an outside corner, responding by speaking or by pointing to the response locations.", "id": 119, "score": 10.5, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [14], "q": "What did Brooks (1968) find in the F task, and why?", "a": "Speaking was easier than pointing, because holding the F used the visuospatial sketchpad and pointing to spatially arranged responses added a competing spatial demand.", "id": 120, "score": 10.5, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [15], "q": "What does the opposite pattern in Brooks (1968) show?", "a": "A task is easier when the information held and the operation performed involve different types of short-term memory. The opposite response advantages support some independence between verbal and visual–spatial memory.", "id": 121, "score": 7.75, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [17], "q": "What did Shepard and Metzler (1971) have participants do?", "a": "They presented pairs of block-built objects at different orientations, and participants judged whether the objects matched despite the difference in orientation.", "id": 122, "score": 9.0, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [17], "q": "What is mental rotation, and what are picture-plane and depth rotation?", "a": "Mental rotation is turning a representation in mind to compare how its parts line up. Picture-plane rotation changes orientation within the flat viewing plane, and depth rotation changes it in three-dimensional space.", "id": 123, "score": 8.0, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [17], "q": "What did Shepard and Metzler (1971) find about reaction time?", "a": "For picture-plane pairs, reaction time increased as the angle of rotation increased, approximately linearly. A larger angle requires a larger mental transformation, which fits an active operation on a spatial representation.", "id": 124, "score": 9.0, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [18], "q": "What does the central executive do in executive control?", "a": "It directs and maintains attention, including focusing, dividing attention and switching it. It also suppresses irrelevant information, coordinates the sketchpad and the phonological loop, and performs calculations.", "id": 125, "score": 6.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [18], "q": "What are updating, shifting and inhibition in Miyake and colleagues (2000)?", "a": "Updating changes the information currently maintained, shifting changes the task or operation being performed, and inhibition suppresses information or responses that interfere with the current goal.", "id": 126, "score": 7.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [18], "q": "Why is the central executive sometimes called a homunculus?", "a": "A homunculus is a little internal agent given the job of controlling everything else. Naming a controller does not explain how control is done, so separating updating, shifting and inhibition specifies different operations.", "id": 127, "score": 6.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [18], "q": "What do focusing, dividing and switching attention refer to in executive control?", "a": "They are operations that control processing: focusing on relevant information, dividing attention across demands and switching attention when the task changes.", "id": 128, "score": 6.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [19], "q": "What is the episodic buffer, and what is its capacity?", "a": "Baddeley (2000) added it as a fourth component. It has a limited capacity of about four chunks, where a chunk is a unit that combines related information.", "id": 129, "score": 6.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [19], "q": "What does the episodic buffer do?", "a": "It binds information from the phonological loop, the visuospatial sketchpad and long-term memory into integrated episodes. Binding means keeping different kinds of information together as a connected representation.", "id": 130, "score": 6.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [19], "q": "What evidence supports the episodic buffer?", "a": "People can immediately recall about 16 words from a meaningful sentence, beyond their span for unrelated words, and some amnesic patients can immediately recall a just-heard story.", "id": 131, "score": 6.375, "tier": "low"}, {"module": 9, "kind": "slide", "slides": [20], "q": "What did Vogel and colleagues (2005) measure first?", "a": "They measured participants’ working-memory capacity to distinguish higher- and lower-capacity groups, and then recorded event-related potentials, ERPs, which are electrical brain responses measured in relation to a task event.", "id": 132, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [20], "q": "What was the task in Vogel and colleagues (2005)?", "a": "A cue directed attention to one side, red bars were shown for 100 milliseconds, a 900 millisecond retention interval followed with the bars absent, and then a test display asked whether a relevant orientation had changed.", "id": 133, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [20], "q": "Why were irrelevant blue bars included in Vogel and colleagues (2005)?", "a": "Ignoring the blue bars required selection within the display, so comparing target-only and distractor conditions tested how irrelevant items entered working-memory processing.", "id": 134, "score": 6.75, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [21], "q": "How did the ERP response behave in Vogel and colleagues (2005)?", "a": "It continues into the retention interval after the display disappears. It has a negative polarity, so a larger response means a stronger negative deflection.", "id": 135, "score": 7.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [21], "q": "What happened for high-capacity participants in Vogel and colleagues (2005)?", "a": "The response was greater with four relevant items than with two, and adding two irrelevant blue items to two relevant items changed little, so they kept the distractors out.", "id": 136, "score": 7.375, "tier": "high"}, {"module": 9, "kind": "slide", "slides": [21], "q": "What happened for low-capacity participants in Vogel and colleagues (2005)?", "a": "Adding the irrelevant items increased the response toward the four-item condition, so more of the irrelevant material entered working-memory processing.", "id": 137, "score": 7.375, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [22], "q": "How are working-memory capacity and filtering efficiency related in Vogel and colleagues (2005)?", "a": "They are positively correlated. Participants with higher capacity tend to have higher filtering efficiency, meaning they exclude irrelevant items more effectively.", "id": 138, "score": 7.0, "tier": "mid"}, {"module": 9, "kind": "slide", "slides": [22], "q": "What does Vogel and colleagues’ (2005) result mean for individual differences in working memory?", "a": "People with higher capacity are less distracted by irrelevant items, and a lower score can reflect competing material occupying processing that targets needed. Differences include selection and control, not only how much relevant information is retained.", "id": 139, "score": 7.0, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [2, 4], "q": "How is working memory different from the single short-term store of the modal model?", "a": "The modal model has one short-term component for temporary availability, while working memory has separate components for verbal, visual–spatial and integrated information, plus executive control, and it includes manipulation of information.", "id": 140, "score": 7.0, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [2, 3], "q": "Why does the 43 × 6 example need more than a store?", "a": "The retained 8 is storage, but carrying the 1 and performing the next multiplication and addition are operations, so the system must both hold and manipulate information.", "id": 141, "score": 6.175, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [5, 6], "q": "How do the phonological loop and the visuospatial sketchpad differ, and how does the central executive relate to them?", "a": "The loop maintains verbal and auditory information and the sketchpad maintains visual and spatial information. The central executive is not a store but coordinates both, directs attention and draws on long-term memory.", "id": 142, "score": 5.4, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [7, 10, 11], "q": "How do the three phonological loop effects relate to the same underlying process?", "a": "Similarity depends on sound-based codes, word length depends on rehearsal time, and suppression occupies the rehearsal process, so they are different aspects of verbal maintenance, and suppression, which occupies rehearsal, also reduces the word-length and similarity effects.", "id": 143, "score": 7.875, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [8, 9], "q": "Why do Conrad’s (1964) results support a sound-based code even for visual letters?", "a": "The letters were seen, but confusions followed sound, such as E replaced by B, so the maintained code was phonological and not visual.", "id": 144, "score": 8.95, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [10], "q": "How do the word-length finding of Baddeley and colleagues (1975, 1984) and Ellis and Hennelly (1980) show the same principle?", "a": "Both show that span depends on how long items take to say. Long words and Welsh number names take longer to rehearse, so fewer items fit in about 1.5 to 2 seconds.", "id": 145, "score": 9.875, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [5, 19], "q": "How do the phonological store, the sketchpad and the episodic buffer each hold a different kind of information?", "a": "The phonological store holds verbal and auditory information, the visuospatial sketchpad holds visual and spatial information, and the episodic buffer binds information from the loop, the sketchpad and long-term memory into integrated episodes.", "id": 146, "score": 6.7, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [13, 14, 15], "q": "How do Brooks’s (1968) two tasks together show that verbal and visual–spatial memory are partly independent?", "a": "The sentence task was easier with pointing and the F task was easier with speaking. In each case the response was easier when it used a different type of memory from the one holding the information.", "id": 147, "score": 10.633, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [13, 14, 15, 20, 21], "q": "How do Vogel and colleagues (2005) and Brooks (1968) each use a competing or irrelevant demand to learn about working memory?", "a": "Brooks (1968) varied whether the response used speaking or pointing and found it was easier when it used a different type of memory from the one holding the information. Vogel and colleagues (2005) added irrelevant blue bars and found that higher-capacity participants kept them out.", "id": 148, "score": 10.23, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [2, 17], "q": "How is the mental rotation result of Shepard and Metzler (1971) related to the idea of operating on a representation?", "a": "In Shepard and Metzler (1971), the linear increase in reaction time with angle suggests an active transformation of a spatial representation, which matches working memory as manipulation and not only storage.", "id": 149, "score": 9.25, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [5, 18], "q": "How does the central executive’s control differ from the contents held in the stores?", "a": "The executive directs attention, suppresses irrelevant information and coordinates components, while the stores hold verbal or visual–spatial contents. Updating, shifting and inhibition describe operations of control.", "id": 150, "score": 6.7, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [18], "q": "Why was the central executive called a homunculus, and how do Miyake and colleagues (2000) respond?", "a": "Naming a controller does not itself explain how control is performed, and separating updating, shifting and inhibition in Miyake and colleagues (2000) specifies different operations.", "id": 151, "score": 7.875, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [4, 19], "q": "Why was the episodic buffer needed beyond the loop and the sketchpad?", "a": "People recall about 16 words of a meaningful sentence, beyond their span for unrelated words, and amnesic patients can immediately recall a story, which suggests an integrated temporary store using long-term knowledge.", "id": 152, "score": 6.7, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [19], "q": "How do the episodic buffer’s four-chunk capacity and the 16-word sentence result fit together?", "a": "The slide frames capacity as about four chunks, which are organized units and not necessarily four individual words, and meaningful material can exceed the span for unrelated words.", "id": 153, "score": 6.875, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [18, 21, 22], "q": "How does the filtering finding of Vogel and colleagues (2005) relate to the central executive’s functions?", "a": "Differences in capacity include selection and control, and the executive’s functions include suppressing irrelevant information and directing attention.", "id": 154, "score": 7.825, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [20, 21, 22], "q": "Why is capacity in Vogel and colleagues (2005) about which items get in and not just how many are shown?", "a": "High-capacity participants kept blue distractors out, while low-capacity participants let them in, so effective capacity depends on selection.", "id": 155, "score": 7.742, "tier": "mid"}, {"module": 9, "kind": "relate", "slides": [8, 13, 14], "q": "How do the tasks of Conrad (1964) and Brooks (1968) show different components of working memory?", "a": "Conrad’s letter confusions show phonological loop coding, while Brooks’s tasks show competition within a component, speaking competing with the loop in the sentence task and pointing competing with the sketchpad in the F task.", "id": 156, "score": 10.85, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [12, 14, 17], "q": "How do Shepard and Metzler (1971) and Brooks (1968) each show what the visuospatial sketchpad does?", "a": "Shepard and Metzler (1971) found that reaction time rose with the angle of rotation, which fits an operation on a spatial representation. Brooks (1968) found that holding the shape of an F used the sketchpad, so pointing to spatially arranged responses competed with it.", "id": 157, "score": 9.817, "tier": "high"}, {"module": 9, "kind": "relate", "slides": [2, 3, 4], "q": "What does working memory add to a single short-term store?", "a": "A single short-term store keeps information temporarily available, and working memory adds operations performed on held information, as in calculation, reasoning and comprehension, with separate components and executive control.", "id": 158, "score": 6.367, "tier": "low"}, {"module": 9, "kind": "relate", "slides": [8, 9, 10], "q": "How do Conrad (1964) and Ellis and Hennelly (1980) each show that verbal memory depends on speech sounds?", "a": "Conrad (1964) found that seen letters were confused by their spoken names, and Ellis and Hennelly (1980) found that digit span was shorter in Welsh because the number names take longer to pronounce.", "id": 159, "score": 9.258, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [2], "q": "What is a problem?", "a": "A problem involves an obstacle between a present state and a goal, with a solution that is not immediately obvious.", "id": 160, "score": 2.45, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [2], "q": "What are the present state and the goal?", "a": "The present state describes the situation as it currently exists, and the goal describes the situation the person is trying to reach. The obstacle prevents an immediate move from one to the other.", "id": 161, "score": 2.45, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [2], "q": "Why does knowing the goal not solve the problem, as in the numbered-tile puzzle?", "a": "A person can identify exactly what counts as a solution and still have a problem, because the sequence of moves that produces it is unclear.", "id": 162, "score": 1.75, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [3], "q": "What is the Gestalt approach to problem solving?", "a": "Gestalt psychologists took a perceptual approach to learning, problem solving and attitudes and beliefs as well as perception, and Koffka (1935) is associated with this approach. Problem solving involves representing a problem in the mind.", "id": 163, "score": 9.45, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [3], "q": "What is restructuring?", "a": "Restructuring means reorganizing the problem’s representation, so a previously hidden relationship becomes usable.", "id": 164, "score": 9.45, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [3], "q": "How is Köhler’s circle problem solved?", "a": "The black line is one diagonal of a rectangle whose lower-right corner is at the circle’s center, and the dashed line from the upper-left corner on the circle to the center is a radius. The diagonals of a rectangle are equal, so x = r.", "id": 165, "score": 8.75, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [4], "q": "What is insight?", "a": "Insight is the sudden realization of a problem’s solution after perceiving an object or problem one way and then representing it differently.", "id": 166, "score": 5.075, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [4], "q": "What is the Aha experience?", "a": "Gestalt psychologists connected insight with the Aha experience, in which the person goes suddenly from not having the solution to recognizing it, instead of feeling a series of increasingly complete steps.", "id": 167, "score": 5.075, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [4], "q": "Is every problem solved with an Aha experience?", "a": "No. Some problems permit a more methodical process in which successive operations bring the person closer to an answer.", "id": 168, "score": 4.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [5], "q": "What did Metcalfe and Wiebe (1987) compare?", "a": "They compared insight problems, including the triangle and chain problems, with noninsight problems, including algebra, and had participants judge how close they felt to a solution.", "id": 169, "score": 9.375, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [5], "q": "What were Metcalfe and Wiebe’s (1987) predictions for insight and noninsight problems?", "a": "For insight problems, people would not be very good at anticipating how near they were to a solution. For noninsight problems, successive operations would give information about progress, so perceived closeness should rise as the solution approaches.", "id": 170, "score": 9.375, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [5], "q": "How were warmth judgments collected in Metcalfe and Wiebe (1987)?", "a": "Participants made warmth judgments every 15 seconds, with hot meaning close to the solution and colder meaning farther away.", "id": 171, "score": 9.375, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [6], "q": "How is the triangle problem solved?", "a": "Ten dots form an upward triangle and exactly three must move to make it point down. The top dot becomes a new bottom point beneath the center of the bottom row, and the two outer dots of the bottom row move to the ends of the two-dot row.", "id": 172, "score": 3.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [6], "q": "How is the chain problem solved?", "a": "Opening a link costs 2 cents, closing costs 3 and the budget is 15, so three opened-and-closed links are possible. One three-link section is opened into three links that join the other three sections into a closed loop.", "id": 173, "score": 3.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [6], "q": "Why must seven dots stay in place in the triangle problem?", "a": "The task is to move exactly three dots, so relocating the entire arrangement would violate it.", "id": 174, "score": 3.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [7], "q": "What did the warmth ratings show for algebra and for insight problems in Metcalfe and Wiebe (1987)?", "a": "In Metcalfe and Wiebe (1987), ratings for algebra increased gradually as the solution approached. For insight problems, warmth stayed low until close to the solution and then jumped sharply, from about 3 to 7.", "id": 175, "score": 9.375, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [7], "q": "What do the warmth results in Metcalfe and Wiebe (1987) suggest about insight?", "a": "In Metcalfe and Wiebe (1987), a low rating shortly before an insight solution means the person did not yet feel close even though the answer was imminent, so insight differs from methodical noninsight solving.", "id": 176, "score": 9.375, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [8], "q": "What is fixation?", "a": "Fixation is a tendency to focus on a specific characteristic of a problem in a way that prevents a solution, and Gestalt psychologists treated it as a major obstacle.", "id": 177, "score": 7.075, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [8], "q": "What is functional fixedness?", "a": "Functional fixedness restricts an object to its familiar functions.", "id": 178, "score": 7.075, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [8], "q": "How is the candle problem solved?", "a": "The matchbox is attached to the corkboard with a tack and used as a platform for the candle, so the candle can burn without dripping wax on the floor.", "id": 179, "score": 6.375, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [8], "q": "What happened when participants were given empty matchboxes in the candle problem?", "a": "They were twice as likely to solve the problem, because separating the box from its familiar contents made it easier to treat it as an object with another use.", "id": 180, "score": 6.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [9], "q": "How is the two-string problem solved?", "a": "A pair of pliers is tied to one string and used as a weight. Setting that string swinging makes a pendulum, so the person can hold the other string and catch the weighted one.", "id": 181, "score": 7.125, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [9], "q": "How does functional fixedness appear in the two-string problem?", "a": "The familiar tool function of the pliers prevents their use as a weight, since the useful property is weight and not the ability to grip.", "id": 182, "score": 7.125, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [10], "q": "What happened when the experimenter accidentally set a string in motion?", "a": "Most participants were able to solve the problem, because the moving string made its use as a pendulum available.", "id": 183, "note": "In the original study the experimenter set the string moving deliberately, not accidentally, as the slide words it.", "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [10], "q": "What is a mental set?", "a": "A mental set is a preconceived notion about how to approach a problem, based on past experience with that problem or similar problems. It concerns the method of solving.", "id": 184, "score": 7.45, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [10], "q": "What is the water-jug problem?", "a": "It asks for a required amount of water using three empty jugs with specified capacities.", "id": 185, "score": 7.45, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [11], "q": "How does the water-jug procedure B − A − 2C work?", "a": "In the first problem A holds 21 quarts, B holds 127, C holds 3 and the goal is 100. Filling B and removing one A-sized amount leaves 106, removing one C-sized amount leaves 103, and a second leaves 100.", "id": 186, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [11], "q": "How does a mental set hide a simpler solution in problems 7 and 8?", "a": "In problem 7 (A 15, B 39, C 3, goal 18) the familiar method works, but A + C gives 18 directly. In problem 8 (A 28, B 59, C 3, goal 25) A − C gives 25 directly, so the set inhibits a simpler solution even though the familiar one still works.", "id": 187, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [12], "q": "What did Newell and Simon (1956) develop, and how did they describe problem solving?", "a": "They developed the Logic Theorist and described problem solving as a process involving search, which includes the activity between posing a problem and its solution.", "id": 188, "score": 8.5, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [12], "q": "What is a problem space?", "a": "A problem space includes an initial state, the intermediate states and a goal state. Knowing the initial and goal states does not specify which intermediate states connect them.", "id": 189, "score": 8.2, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [13], "q": "What are operators?", "a": "Operators are rules specifying which moves are allowed and which are not. Applying one changes the problem from one state to another.", "id": 190, "score": 8.2, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [13], "q": "What are the rules of the Tower of Hanoi?", "a": "A move transfers one disk at a time, a disk can be moved only when no other disk is on top of it, and a larger disk cannot be placed on top of a smaller disk, even in intermediate arrangements.", "id": 191, "score": 8.2, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [13], "q": "What are the initial, goal and intermediate states in the Tower of Hanoi?", "a": "The starting stack is the initial state, the completed stack on the target peg is the goal state, and temporary distributions across the pegs are intermediate states.", "id": 192, "score": 7.5, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [14], "q": "Why does the Tower of Hanoi need repeated rearrangements?", "a": "Smaller disks must be moved out of the way before a larger disk becomes available, and after the largest disk is moved the smaller disks must be rearranged onto it in order.", "id": 193, "score": 3.0, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [14], "q": "How long would the 64-disk Tower of Hanoi take?", "a": "Roughly a trillion years, even if every correct move took one second, because the number of required moves is very large.", "id": 194, "note": "The minimum for 64 disks is 2^64 − 1 moves, which at one move per second is about 585 billion years, so a trillion years is a rounded overstatement.", "score": 3.0, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [15], "q": "What are the initial and goal arrangements of the numbered-tile puzzle?", "a": "The initial rows are 8–empty–6, 5–4–7 and 2–3–1, and the goal rows are empty–1–2, 3–4–5 and 6–7–8.", "id": 195, "score": 4.825, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [15], "q": "Why is having all the tiles on the board not enough in the tile puzzle?", "a": "A tile being present on the board does not mean its required position has been achieved. The current state has to be related to the goal through an allowable sequence of moves.", "id": 196, "score": 4.125, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [16], "q": "What is a search tree?", "a": "A search tree represents possible states of a tile puzzle and the moves connecting them. Each state can have several successors, so the solver chooses which branches to pursue.", "id": 197, "score": 7.45, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [16], "q": "What are the legal moves from the start 2–8–3, 1–6–4, 7–empty–5?", "a": "The empty location can shift left, up or right by exchanging position with the adjacent tile, and each result is a different intermediate state with the same eight tiles.", "id": 198, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [16], "q": "What do the numbered labels and the small boards show in the search tree?", "a": "The numbered labels identify positions in the search, and the small boards specify the actual tile arrangements.", "id": 199, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [17], "q": "What is means–end analysis?", "a": "Means–end analysis organizes the search around reducing the difference between the current situation and the goal, by considering which changes would remove an obstacle.", "id": 200, "note": "The slides give no year for means–end analysis. The 1956 date belongs to the Logic Theorist, and means–end analysis is usually dated to Newell and Simon’s later General Problem Solver work.", "score": 8.2, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [17], "q": "What is a subgoal?", "a": "A subgoal is a condition that makes part of the larger task possible, not the complete final answer. Achieving it can reduce an obstacle that prevents a required move.", "id": 201, "score": 8.2, "tier": "high"}, {"module": 10, "kind": "slide", "slides": [18], "q": "What are the three subgoals in the Tower of Hanoi?", "a": "First, free the large disk by moving the smaller disks off it. Second, free the third peg by moving the smallest disk from it onto the stack on the middle peg. Third, move the large disk from the starting peg to the third peg.", "id": 202, "score": 7.075, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [18], "q": "Why do the Tower of Hanoi subgoals address different obstacles?", "a": "One removes the material above the disk that must move, and another removes an obstruction at its destination, so several coordinated changes are needed before the overall move becomes legal.", "id": 203, "score": 6.375, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [19], "q": "How can the way a problem is stated change its difficulty?", "a": "The wording and presentation influence which relationships become part of the representation, so a useful property can be easier or harder to recognize even when the underlying task is the same.", "id": 204, "score": 4.125, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [19], "q": "What is the mutilated-checkerboard problem?", "a": "It concerns covering a board with dominoes after squares have been removed, asking whether the covering is possible under the domino constraints.", "id": 205, "score": 4.825, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [19], "q": "What does Newell and Simon’s approach provide for specifying a solution?", "a": "A way to specify possible pathways from an initial state to a goal state. Identifying states and possible transitions makes the search explicit, and a solution requires an allowable route between the beginning and the required endpoint.", "id": 206, "score": 4.125, "tier": "low"}, {"module": 10, "kind": "slide", "slides": [20], "q": "Why can opposite removed corners not be covered by 31 dominoes?", "a": "Removing two opposite corners leaves 62 squares, matching the area of 31 dominoes, but every domino covers one square of each color and the two removed corners are the same color. The remaining board has unequal colors, so the covering is impossible.", "id": 207, "score": 7.125, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [20], "q": "Does equal total area guarantee that dominoes can cover the board?", "a": "No. 62 squares matches the area of 31 dominoes, but equal area does not guarantee a legal arrangement, because every domino must cover one square of each color.", "id": 208, "score": 7.125, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [21], "q": "What conditions varied how the board squares were described?", "a": "Participants received a blank board, a colored board, a board labeled black and pink, or one labeled bread and butter.", "id": 209, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [21], "q": "What did the bread-and-butter condition show?", "a": "Participants solved it twice as fast as the blank condition, because the labels emphasized the pairing of the two kinds of square and made the constraint easier to represent.", "id": 210, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [22], "q": "What is a think-aloud protocol?", "a": "A person says aloud what they are thinking while solving a problem, verbalizing new thoughts instead of describing their actions.", "id": 211, "score": 7.45, "tier": "mid"}, {"module": 10, "kind": "slide", "slides": [22], "q": "What do think-aloud reports show in the bread-and-butter checkerboard?", "a": "Participants reach the solution after recognizing that the words bread and butter are relevant to the required pairing. Their thinking shifts from squares as positions to the relationship between two kinds of square, which is a representational shift related to restructuring.", "id": 212, "score": 6.75, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [3, 4, 12], "q": "How does the Gestalt approach differ from the search approach of Newell and Simon (1956)?", "a": "The Gestalt approach emphasizes how a problem is represented and restructured, with insight as a sudden realization. Newell and Simon describe solving as searching a problem space of states using operators.", "id": 213, "score": 9.5, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [4, 5, 7], "q": "How do insight and noninsight problems differ in the experience of progress?", "a": "In Metcalfe and Wiebe (1987), algebra warmth rose gradually, while insight warmth stayed low and then jumped sharply, so insight does not give a steady feeling of getting closer.", "id": 214, "score": 8.342, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [3, 4], "q": "How are restructuring and insight related?", "a": "Restructuring is the change in representation, and insight is the sudden realization that follows once a crucial element is found in the new representation.", "id": 215, "score": 8.375, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [8, 10], "q": "How do functional fixedness and mental set differ?", "a": "Functional fixedness restricts an object to its familiar function, while a mental set is a preconceived approach to solving based on past experience. Both are obstacles to solving, but one concerns objects and the other concerns methods.", "id": 216, "score": 7.175, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [8, 9], "q": "How do the candle problem and the two-string problem both involve functional fixedness?", "a": "In each, an everyday object, a matchbox or pliers, has a familiar function that blocks seeing its useful property, a platform or a weight.", "id": 217, "score": 7.475, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [9, 10], "q": "Why does the swinging-string hint count as restructuring?", "a": "The hanging string changes from something to be reached where it is into something that can be made to swing within reach, so the representation changes.", "id": 218, "score": 7.55, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [8, 21], "q": "How do the empty matchboxes in the candle problem and the bread-and-butter labels in the checkerboard both show that presentation changes difficulty?", "a": "Participants given empty matchboxes were twice as likely to solve the candle problem, and participants given bread-and-butter labels solved the checkerboard twice as fast as the blank condition. In each case the presentation made a useful relationship easier to represent.", "id": 219, "score": 7.175, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [10, 11], "q": "How do the water-jug problems show that past success can hurt?", "a": "Repeated success with B − A − 2C builds a mental set, so the simpler A + C or A − C solutions can be missed even though the familiar method still works.", "id": 220, "score": 7.25, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [12, 13, 16], "q": "How are initial, intermediate and goal states, operators and search related?", "a": "Operators define legal moves that change one state into another, and search is finding a sequence of those moves from the initial state through intermediate states to the goal.", "id": 221, "score": 7.9, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [13, 15, 16], "q": "How do the Tower of Hanoi and the tile puzzle both illustrate a problem space?", "a": "Each has an initial state, a goal state, intermediate states and rules for legal moves, and solving requires choosing a route through those states.", "id": 222, "score": 7.45, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [17, 18], "q": "Why can a subgoal be a temporary arrangement that is not the final stack?", "a": "A subgoal makes a later required move legal, such as freeing the large disk, even though the temporary arrangement is not the goal.", "id": 223, "score": 7.775, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [12, 17, 18], "q": "How does means–end analysis relate to search?", "a": "It organizes search around reducing the difference between the current state and the goal, using subgoals.", "id": 224, "score": 7.85, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [3, 19, 21], "q": "How do problem statement and the Gestalt idea of representation connect?", "a": "Both say that the way a problem is represented, including wording and labels, changes which relationships are noticed and therefore how hard it is.", "id": 225, "score": 8.367, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [19, 20], "q": "How does the mutilated-checkerboard solution use a constraint that applies to all placements?", "a": "The color pairing of every domino and the same-color removed corners show impossibility without trying individual placements.", "id": 226, "score": 7.025, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [3, 21, 22], "q": "Why did bread and butter help, and how does this relate to restructuring?", "a": "The labels pointed toward the pairing of two kinds of square, which changed how squares were represented, matching the Gestalt idea that representation shifts make the solution available.", "id": 227, "score": 8.717, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [22], "q": "How does the think-aloud method let researchers see a representational shift?", "a": "Verbal reports show when the pairing of the two labels entered the person’s reasoning, so the shift from squares as positions to a relationship can be observed during the attempt.", "id": 228, "score": 7.25, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [5, 6], "q": "Why do the triangle and chain problems count as insight problems in Metcalfe and Wiebe (1987)?", "a": "They are solved by a change in representation, such as using a whole section as connecting links, and they were compared with algebra, which has a more methodical route.", "id": 229, "score": 8.875, "tier": "high"}, {"module": 10, "kind": "relate", "slides": [8, 10, 14], "q": "How are the Gestalt obstacles to solving different from limits of a search?", "a": "Fixation, functional fixedness and mental set are obstacles from how the problem is represented or approached, while the 64-disk Tower of Hanoi shows that the number of required moves can be very large.", "id": 230, "score": 6.7, "tier": "low"}, {"module": 10, "kind": "relate", "slides": [2, 3, 12], "q": "What do all the problem types share about a present state, a goal and an obstacle?", "a": "Each has an obstacle between a present state and a goal, and the solution is found by restructuring the representation or by searching for a route.", "id": 231, "score": 8.15, "tier": "mid"}, {"module": 10, "kind": "relate", "slides": [4, 5, 7], "q": "How do insight problems and noninsight problems differ in how a solution is reached?", "a": "Insight is a sudden realization after restructuring, and in Metcalfe and Wiebe (1987) warmth for insight problems stayed low and then jumped sharply. Noninsight problems such as algebra allow a more methodical process, and warmth rose gradually.", "id": 232, "score": 8.342, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [2], "q": "How do reorganization and insight relate to problem representation?", "a": "A person can initially organize the elements in a way that hides a useful relationship. Reorganizing the representation can make a solution available, sometimes with the sudden realization associated with insight.", "id": 233, "score": 1.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [2], "q": "What is problem solving as search?", "a": "It concerns the activity between posing a problem and reaching its solution, finding a route through possible states. Specifying the starting conditions and the goal does not identify the sequence that connects them.", "id": 234, "score": 1.7, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [2], "q": "How can the statement of a problem affect its difficulty?", "a": "The presentation influences the relationships a person represents. In the mutilated checkerboard, considering total area hides the constraint that considering the pairing of different-colored squares makes available.", "id": 235, "score": 1.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [3], "q": "What is the Russian marriage problem?", "a": "There are 32 bachelors and 32 unmarried women, and a matchmaker arranges 32 heterosexual marriages. Two bachelors die, leaving 62 survivors, 30 men and 32 women, and the question is whether 31 heterosexual marriages can be formed.", "id": 236, "score": 4.075, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [3], "q": "Why is the answer to the Russian marriage problem no?", "a": "The two groups no longer have equal numbers, so at most 30 marriages can be formed and two women are left without a partner. Dividing 62 by two gives 31 pairs by total size, but that does not satisfy the requirement about which kinds of person each pair must contain.", "id": 237, "score": 3.375, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [4], "q": "How does the mutilated checkerboard have the same structure as the Russian marriage problem?", "a": "A domino covers two adjacent squares of different colors, and removing two opposite corners removes two squares of the same color. The colors are then unequal even though 62 squares matches the area of 31 dominoes.", "id": 238, "score": 3.75, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [4], "q": "Why can rearranging the dominoes not fix the imbalance?", "a": "Every complete covering would have to pair each square of one color with a square of the other, and one color is more numerous, so some squares would remain unmatched however the dominoes move.", "id": 239, "score": 3.75, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [5], "q": "What is analogical problem solving?", "a": "It uses the solution to a similar problem to guide the solution to a new problem. The target problem is the one currently being solved, and a source problem shares relevant similarities with it.", "id": 240, "score": 8.2, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [5], "q": "How does the Russian marriage problem map onto the mutilated checkerboard?", "a": "Marriages correspond to dominoes, the two groups of people correspond to the two square colors, and removing two bachelors corresponds to removing two same-colored squares.", "id": 241, "score": 7.5, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [5], "q": "What is analogical transfer?", "a": "It is the transfer from the source problem to the target problem. The useful information is the relationship among the elements, not their identical appearance.", "id": 242, "score": 8.2, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [6], "q": "What is Duncker’s radiation problem?", "a": "A patient has a malignant tumor in the stomach that cannot be operated on, and a ray can destroy the tumor if sufficiently high intensity reaches it at once.", "id": 243, "score": 8.825, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [6], "q": "Why does a single ray fail in Duncker’s radiation problem?", "a": "A high-intensity ray would also destroy the healthy tissue it passes through, and a low-intensity ray would spare the tissue but not destroy the tumor.", "id": 244, "score": 8.125, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [6], "q": "How is Duncker’s radiation problem solved, and how many people solve it without an analogy?", "a": "Several low-intensity rays converge on the tumor from different directions at the same time, so the combined intensity at the tumor is sufficient. Only about 10 percent of participants reach this without the helpful analogy.", "id": 245, "score": 8.125, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [7], "q": "What is the fortress problem?", "a": "A rebel general has an army strong enough to capture a dictator’s fortress if the entire force attacks it, but mines on each road detonate when a large force travels together.", "id": 246, "score": 3.7, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [7], "q": "How is the fortress problem solved?", "a": "The general divides the army into small groups that approach along different roads, each below the danger threshold, and the groups arrive together so their combined force can attack.", "id": 247, "score": 3.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [8], "q": "How do the fortress and radiation solutions correspond?", "a": "The fortress corresponds to the tumor, the small groups correspond to low-intensity rays and the roads correspond to paths through surrounding tissue. Sending one large force down one road corresponds to one damaging high-intensity ray.", "id": 248, "score": 6.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [8], "q": "Why is convergence required and not merely dividing the force?", "a": "Timing matters because the separate contributions must combine at the target. Dividing the army or lowering every ray’s intensity without combining the effects leaves the target requirement unmet.", "id": 249, "score": 6.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [9], "q": "What are noticing, mapping and applying in Gick and Holyoak’s analogy steps?", "a": "Noticing is recognizing that a source problem may be relevant, mapping connects the elements and relationships of the source to the target, and applying uses the correspondences to generate a parallel solution. Noticing is crucial and can be the most difficult.", "id": 250, "score": 7.375, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [9], "q": "What happened after participants read the fortress story in Gick and Holyoak’s study?", "a": "In Gick and Holyoak’s study, about 30 percent solved the radiation problem, so having the story available did not guarantee spontaneous use of its solution.", "id": 251, "score": 7.375, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [9], "q": "What happened when participants were told to think about the story in Gick and Holyoak’s study?", "a": "In Gick and Holyoak’s study, success rose to about 75 percent, because the reminder made a relevant source available for mapping and application.", "id": 252, "score": 7.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [10], "q": "What are surface features?", "a": "They are the specific elements of a problem, such as a fortress, an army, a tumor or a ray. Two problems can use very different objects while sharing the relationship needed for a solution.", "id": 253, "score": 7.075, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [10], "q": "How can surface features hide a shared relationship, and how can they help?", "a": "A fortress and a tumor do not look alike, which can keep a person from noticing the shared need for a strong combined effect. Making surface features more similar can make the relationship easier to notice.", "id": 254, "score": 6.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [11], "q": "What is the lightbulb problem?", "a": "Ruth finds an expensive laboratory lightbulb with a broken filament in sealed glass, and must fuse the filament without opening the bulb. A high-intensity laser would break the fragile glass, and a low-intensity beam would not fuse the filament.", "id": 255, "score": 4.075, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [11], "q": "How is the lightbulb problem solved?", "a": "Several low-intensity laser beams are directed toward the filament from different directions at once, so the combined effect fuses the filament while each part of the glass receives only a low-intensity beam.", "id": 256, "score": 3.375, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [12], "q": "How well does Duncker’s radiation problem work as a source for the lightbulb problem?", "a": "About 81 percent of participants who knew the radiation problem solved the lightbulb problem, compared with about 10 percent in the control group.", "id": 257, "score": 8.5, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [12], "q": "Why is a connection between the radiation problem and the lightbulb problem easier to notice than one between the radiation problem and the fortress?", "a": "The tasks share relatively similar surface features, since both direct a beam toward an internal target, which makes a possible connection easier to notice.", "id": 258, "score": 8.5, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [13], "q": "What are structural features?", "a": "Structural features are the underlying principle that governs the solution. In the radiation and fragile-glass problems, a strong beam would damage the surroundings on its way to an internal target.", "id": 259, "score": 7.45, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [13], "q": "Why can two lightbulb versions have the same surface features but different structure?", "a": "The same bulb, filament and lasers keep surface features similar, but changing why a single laser fails changes the relationship to the radiation target.", "id": 260, "score": 6.75, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [14], "q": "How does the fragile-glass version match the radiation problem?", "a": "A high-intensity beam would break the surrounding glass just as it would damage healthy tissue, so the source’s reason for using convergence corresponds to the target’s.", "id": 261, "score": 7.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [14], "q": "How many participants solved the radiation problem after the fragile-glass source?", "a": "About 69 percent.", "id": 262, "score": 7.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [15], "q": "What is the insufficient-intensity version?", "a": "The laser only generates low-intensity beams that cannot fuse the filament, and several lasers combine to supply enough intensity. There is no surrounding-damage constraint.", "id": 263, "score": 8.075, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [15], "q": "How did transfer differ between the insufficient-intensity and fragile-glass sources?", "a": "About 33 percent solved the radiation problem after the insufficient-intensity source, compared with about 69 percent after the fragile-glass source, even though both use converging laser beams.", "id": 264, "score": 7.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [16], "q": "What is analogical encoding?", "a": "It is the process of comparing two problems and determining the similarities between them, which draws attention to relationships that appear in both.", "id": 265, "score": 7.45, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [16], "q": "How does analogical encoding improve analogical problem solving?", "a": "Comparing source stories directs reasoning toward the structural features, so a later target can be approached through the common relationship and not only through one familiar situation.", "id": 266, "score": 6.75, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [17], "q": "What is the analogical paradox?", "a": "It is the contrast between difficulty applying analogies in laboratory tasks and the routine use of analogies in real-world settings.", "id": 267, "score": 6.7, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [17], "q": "How many analogies do scientists use in a laboratory meeting?", "a": "About 3 to 15 analogies in a one-hour laboratory meeting.", "id": 268, "score": 6.0, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [17], "q": "What is in vivo problem-solving research?", "a": "It observes people solving problems in real-world settings, which keeps the ordinary context. It can be time-consuming and researchers cannot isolate and control variables as in a constrained experiment.", "id": 269, "score": 6.7, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [18], "q": "What is an expert?", "a": "An expert is a person recognized as extremely knowledgeable or skilled in a particular field after devoting a large amount of time to learning, practicing and applying that learning.", "id": 270, "score": 2.075, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [18], "q": "How do experts perform compared with beginners?", "a": "A chess expert can have spent roughly 10,000 to 20,000 hours studying and playing, and experts solve problems within their field faster and with a higher success rate than beginners.", "id": 271, "score": 1.375, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [19], "q": "What did Chase and Simon (1973) do?", "a": "They compared a chess master with a beginner who had fewer than 100 hours of experience. Each viewed a chessboard for five seconds and tried to reproduce where the pieces had been, with actual game positions or random arrangements.", "id": 272, "score": 9.0, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [19], "q": "What did Chase and Simon (1973) find?", "a": "The expert did much better for actual game positions, because long-term memory made meaningful arrangements available as chunks. The same chunks were not available for random arrangements.", "id": 273, "score": 9.0, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [20], "q": "How does knowledge organization affect problem solving?", "a": "It affects how information can be accessed, since knowing more is accompanied by differences in how relevant problems are grouped and related to the principles needed to solve them.", "id": 274, "score": 8.0, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [20], "q": "What did Chi et al. (1982) do?", "a": "They presented 24 physics problems to experts, who were physics professors, and novices, who were students with one semester of physics, and participants sorted them into groups by similarity.", "id": 275, "note": "The sorting study is usually cited as Chi, Feltovich and Glaser (1981), with advanced physics PhD students as the experts. Low confidence, so check before relying on it.", "score": 9.0, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [20], "q": "How did novices and experts group the physics problems in Chi et al. (1982)?", "a": "Novices grouped by surface features such as the appearance of the objects, and experts grouped by structural features, including the underlying principles.", "id": 276, "score": 9.0, "tier": "high"}, {"module": 11, "kind": "slide", "slides": [21], "q": "How did the novice and the expert group problem 24 in Chi et al. (1982)?", "a": "In Chi et al. (1982), the novice grouped problems 23 and 24 because both involve inclined planes. The expert grouped problems 21 and 24 through conservation of energy, even though problem 21 has a block and spring on a horizontal surface.", "id": 277, "score": 7.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [22], "q": "How do experts spend their time on problems?", "a": "Experts spend more time analyzing a problem before proceeding, which can pay off in solving the overall problem efficiently.", "id": 278, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [22], "q": "Is the advantage of experts general?", "a": "No. It is specific to their field, and experts are no better than novices on problems outside it.", "id": 279, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [22], "q": "How can expertise limit flexibility?", "a": "Expertise can make a person less open to new ways of looking at a problem, and some problems require rejecting usual procedures for less frequently used ones.", "id": 280, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [23], "q": "What is creativity, and what is divergent thinking?", "a": "Creativity includes innovative thinking, novel ideas and new connections between existing ideas. Divergent thinking is open-ended and allows a large number of potential solutions.", "id": 281, "score": 4.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [23], "q": "What does creative problem solving involve beyond getting an idea?", "a": "It usually includes a lengthy period of trial and error as possibilities are developed and tested.", "id": 282, "score": 4.375, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [23], "q": "What are the four parts of creative problem solving?", "a": "Problem generation, which includes problem finding and fact finding, problem formulation, which includes defining the problem and finding ideas, problem solving, which includes evaluation and planning, and solution implementation, which means taking action.", "id": 283, "score": 5.075, "tier": "mid"}, {"module": 11, "kind": "slide", "slides": [24], "q": "Why are ideas necessary but not enough in creative problem solving?", "a": "Without ideas the process stops, but producing an idea does not complete the evaluation, planning and action involved in carrying a solution out.", "id": 284, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [24], "q": "How can too much knowledge hinder creative problem solving?", "a": "Familiar approaches can constrain which possibilities are considered, so an accepted procedure can dominate the representation even when the problem requires a different relationship.", "id": 285, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "slide", "slides": [24], "q": "What does flexible thinking include?", "a": "Being willing to reject an accepted procedure when it does not fit the problem and reconsidering how knowledge is being used.", "id": 286, "score": 4.0, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [3, 4, 5], "q": "How do the Russian marriage problem and the mutilated checkerboard show analogical transfer?", "a": "The marriage problem is the source and the checkerboard is the target. Marriages map to dominoes and the two groups to the two colors, so recognizing the one-of-each pairing transfers the solution.", "id": 287, "score": 6.95, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [5, 9], "q": "Why do noticing, mapping and applying each matter for analogy?", "a": "Noticing finds a relevant source, mapping connects its elements to the target and applying generates the parallel solution. Gick and Holyoak’s results show that success can fail at noticing even when the source is known.", "id": 288, "score": 7.975, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [6, 7, 8], "q": "How does the fortress problem show the same structure as Duncker’s radiation problem?", "a": "Both require enough force at a central target while limiting what travels along each approach, which is solved by combining weak approaches into a strong effect.", "id": 289, "score": 7.708, "tier": "mid"}, {"module": 11, "kind": "relate", "slides": [9, 12], "q": "How do the 30 and 75 percent results of Gick and Holyoak and the 81 percent lightbulb result together show what helps transfer?", "a": "A reminder to think about the story raised success from about 30 to about 75 percent, so noticing matters. The radiation source gave about 81 percent on the lightbulb problem, so similar surface features also help.", "id": 290, "score": 8.775, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [10, 12, 13], "q": "How do surface features and structural features each affect transfer?", "a": "Similar surface features make a connection easier to notice, as in radiation to lightbulb. Structural features, the constraints that make convergence useful, determine whether the solution applies.", "id": 291, "score": 8.483, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [14, 15], "q": "How did transfer from the fragile-glass source and the insufficient-intensity source compare for the radiation problem?", "a": "About 69 percent solved the radiation problem after the fragile-glass source, which shares the surrounding-damage constraint, and about 33 percent after the insufficient-intensity source, which gives a different reason for converging beams. The different rates accompany a difference in the underlying constraints.", "id": 292, "score": 7.875, "tier": "mid"}, {"module": 11, "kind": "relate", "slides": [9, 16], "q": "How does analogical encoding address the problem shown by Gick and Holyoak?", "a": "Comparing sources draws attention to shared structure, which helps people notice and map relationships that they do not spontaneously use.", "id": 293, "score": 7.75, "tier": "mid"}, {"module": 11, "kind": "relate", "slides": [17], "q": "How do the lab difficulty of analogies and everyday use of analogies fit together?", "a": "That contrast is the analogical paradox, and in vivo research studies analogies in real settings where scientists use many in one meeting, at the cost of experimental control.", "id": 294, "score": 6.5, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [19, 20, 21], "q": "What do Chase and Simon (1973) and Chi et al. (1982) show that is the same about expertise?", "a": "In both, expertise organizes knowledge by meaningful relationships, chunks of piece positions in chess and structural principles in physics.", "id": 295, "score": 9.283, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [19, 20], "q": "How do Chase and Simon (1973) and Chi et al. (1982) differ in what they measure?", "a": "Chase and Simon measured memory for chess positions, while Chi et al. measured how problems are grouped by surface or structural features.", "id": 296, "score": 9.5, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [19], "q": "Why does the chess advantage disappear for random arrangements in Chase and Simon (1973)?", "a": "In Chase and Simon (1973), the expert’s advantage comes from familiar chunks, and randomizing the pieces removes the relationships that experience makes useful.", "id": 297, "score": 9.5, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [10, 20, 21], "q": "How are novices’ surface grouping in Chi et al. (1982) and failures of analogical transfer in Gick and Holyoak related?", "a": "Both reflect attention to surface features, whether similar-looking objects or different-looking scenarios, and not to the structural principle that governs the solution.", "id": 298, "score": 9.067, "tier": "high"}, {"module": 11, "kind": "relate", "slides": [20, 22], "q": "How can the experts’ analysis time and field specificity be explained by knowledge organization?", "a": "Experts’ organized knowledge helps within the field, so extra analysis pays off there, but outside the field the organization does not supply the relationships needed.", "id": 299, "score": 7.7, "tier": "mid"}, {"module": 11, "kind": "relate", "slides": [22, 24], "q": "How do an expert’s accepted procedure and a familiar approach dominating the representation compare?", "a": "Both involve a familiar approach dominating, an accepted procedure for experts and a familiar approach that constrains which possibilities are considered, which can block a better approach.", "id": 300, "score": 4.5, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [2, 5, 8], "q": "How are representation and insight connected to analogy?", "a": "In an analogy the relationship among the elements of a source is used to recognize the relationship in the target, which can make a solution available, as reorganizing a representation can.", "id": 301, "score": 6.983, "tier": "mid"}, {"module": 11, "kind": "relate", "slides": [23, 24], "q": "How does divergent thinking relate to the four parts of creative problem solving?", "a": "Divergent thinking generates many potential solutions, while formulation includes finding ideas, and evaluation, planning and implementation are separate parts that carry an idea through.", "id": 302, "score": 4.8, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [9, 22, 24], "q": "Why do creative problem solving and analogy both depend on how knowledge is used?", "a": "Knowledge helps when it is organized around structure and hurts when a familiar approach dominates, so flexible use and noticing are what matter.", "id": 303, "score": 6.975, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [23], "q": "How are problem generation and problem formulation different from problem solving?", "a": "Generation includes finding the problem and facts, formulation defines the problem and finds ideas, and solving includes evaluation and planning, after which implementation takes action.", "id": 304, "score": 4.875, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [3, 4, 5], "q": "How does the representation of a problem as a pairing explain two different problems?", "a": "The pairing of two groups explains why both 62 survivors and 62 squares cannot be covered in pairs, so one representation solves two surface-different problems.", "id": 305, "score": 6.95, "tier": "low"}, {"module": 11, "kind": "relate", "slides": [10, 13, 14, 15], "q": "How do surface features and structural features each matter when a known solution is used on a new problem?", "a": "Similar surface features make a connection easier to notice, and the structural features, the constraints that make a solution useful, determine whether it applies. The fragile-glass source worked better than the insufficient-intensity source because its structure matched.", "id": 306, "score": 7.713, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [2], "q": "What are decisions, and what is reasoning?", "a": "Decisions are the process of making choices between alternatives, and reasoning is the process of drawing conclusions.", "id": 307, "score": 2.5, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [2], "q": "How are decisions related to judgments?", "a": "Decisions are based on the judgments people make. A judgment can contribute to a decision through an evidence-based inference, with the conclusion expressing what the observations support and the decision concerning what to do.", "id": 308, "score": 2.5, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [2], "q": "What is inductive reasoning?", "a": "Inductive reasoning is one of the primary mechanisms in making judgments. It is reasoning based on observations and reaching conclusions from evidence.", "id": 309, "score": 3.2, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [3], "q": "How certain are inductive conclusions?", "a": "They are probably, but not definitely, true, because the observations support an inference rather than guarantee every case.", "id": 310, "score": 4.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [3], "q": "What does the strength of an inductive argument depend on?", "a": "The representativeness, number and quality of the observations.", "id": 311, "score": 4.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [3], "q": "What does a single black swan among many white swans show?", "a": "Numerous white swans support an expectation about swan color, but a single clearly observed black swan contradicts the claim that every swan is white, so one high-quality observation can carry substantial weight.", "id": 312, "score": 4.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [4], "q": "How is induction used in science and everyday life?", "a": "Scientific discoveries use induction when observations support hypotheses and general conclusions. In everyday life people predict what will happen from what has happened in the past, especially in familiar situations.", "id": 313, "score": 1.75, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [4], "q": "Does inductive reasoning always involve deliberate argument?", "a": "No. Some inductive reasoning happens automatically, because a familiar pattern already supports an expectation.", "id": 314, "score": 1.75, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [5], "q": "What are heuristics?", "a": "Heuristics are shortcuts that help people reach conclusions rapidly using past experience to guide present behavior. They are rules of thumb likely to provide a correct answer but not foolproof.", "id": 315, "score": 5.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [5], "q": "How do the availability and representativeness heuristics differ?", "a": "The availability heuristic uses how readily examples come to mind, and the representativeness heuristic uses how much a case resembles a category.", "id": 316, "score": 4.75, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [6], "q": "What is the availability heuristic?", "a": "It makes events that are more easily remembered seem more probable than events that are harder to remember. The more examples a person can think of, the more probable the event is judged to be.", "id": 317, "score": 7.075, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [6], "q": "What makes an event more available without making it more common?", "a": "Distinctiveness, emotional salience and frequent encoding or retrieval.", "id": 318, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [7], "q": "What is the word judgment about the letter r?", "a": "It asks whether English has more words that begin with r or more words with r as the third letter.", "id": 319, "score": 8.075, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [7], "q": "What do most people answer, and what is correct?", "a": "About 70 percent choose words beginning with r, but words with r in the third position are actually three times more common.", "id": 320, "note": "The three-to-one figure is not verified. The commonly stated ratio is closer to two to one. The direction, that words with r are more common in third position, holds.", "score": 7.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [7], "q": "Why does the availability heuristic produce the r-word error?", "a": "Retrieving words by first letter is easier than searching for a letter in the third position, so words beginning with r come to mind readily and that set feels more numerous.", "id": 321, "score": 7.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [8], "q": "What are the causes-of-death comparisons?", "a": "People judge which of two causes would be more likely to kill a randomly selected person in the United States, such as homicide versus appendicitis, drowning versus an auto–train collision, asthma versus botulism, asthma versus a tornado and appendicitis versus pregnancy.", "id": 322, "score": 4.075, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [8], "q": "Why do people pick the less likely cause of death?", "a": "A death from botulism can become front-page news while deaths from asthma go virtually unnoticed, so distinctive coverage makes the unusual cause more available even though asthma is more likely.", "id": 323, "score": 3.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [8], "q": "In the causes-of-death comparisons, which is more likely, asthma or botulism or a tornado?", "a": "Asthma is more likely than botulism or a tornado, yet many respondents select the less likely cause.", "id": 324, "score": 3.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [9], "q": "What is the representativeness heuristic?", "a": "It bases a judgment on how much one event resembles another, estimating whether A belongs to class B from how well A’s properties resemble those normally associated with B.", "id": 325, "score": 7.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [9], "q": "What is the Robert problem?", "a": "Robert wears glasses, speaks quietly and reads a lot, and many people judge him more likely to be a librarian than a farmer.", "id": 326, "score": 7.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [9], "q": "What is the base rate, and what is base-rate neglect?", "a": "The base rate is the background prevalence of the categories, here about 2.2 million farms and 120,000 libraries in America. Base-rate neglect occurs when a similarity-based response displaces that information.", "id": 327, "note": "The 2.2 million and 120,000 are counts of farms and libraries, not of people in each occupation. Farmers still outnumber librarians, so the conclusion stands, but the comparison is loose.", "score": 6.75, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [10], "q": "What do people do with base rates in the lawyer–engineer problem when no description is given?", "a": "A group has 70 lawyers and 30 engineers, so the chance of picking an engineer is 30 out of 100, and respondents generally use the base rate correctly.", "id": 328, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [10], "q": "What happens when Jack is described?", "a": "Jack is described as conservative, careful, ambitious, and enjoying home carpentry, sailing and mathematical puzzles, and respondents tend to call him an engineer. Descriptive information dominates even though the group still contains more lawyers.", "id": 329, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [11], "q": "What is the conjunction rule?", "a": "The probability of two events occurring together cannot be greater than the probability of either event alone, because adding a requirement restricts the set of cases.", "id": 330, "score": 7.7, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [11], "q": "What is the Linda problem, and why is the common answer an error?", "a": "Linda is described as outspoken, bright, trained in philosophy and concerned with social justice, and about 82 percent choose bank teller and active in the feminist movement over bank teller. Feminist bank tellers are inside the larger set of bank tellers, so the conjunction cannot be more probable.", "id": 331, "score": 7.0, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [12], "q": "What is the hospital question?", "a": "A larger hospital has about 45 births per day and a smaller one about 15, with about half of babies boys, and the question is which hospital records more days when over 60 percent of the babies are boys.", "id": 332, "score": 4.7, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [12], "q": "Why is the answer about the same incorrect?", "a": "That answer, chosen by 56 percent, treats the shared overall proportion as enough and leaves out the difference between observing a proportion in 15 births and in 45 births.", "id": 333, "score": 4.0, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [13], "q": "Which hospital has more days with over 60 percent boys, and why?", "a": "The smaller hospital. Smaller samples vary more from one observation to another, so an extreme proportion is more likely in 15 births than in 45.", "id": 334, "score": 7.75, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [13], "q": "Why is choosing the larger hospital also a mistake?", "a": "It confuses an absolute count with the frequency of an extreme proportion, because the question asks which hospital more often crosses 60 percent.", "id": 335, "score": 7.75, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [14], "q": "What is the law of large numbers?", "a": "As more individuals are randomly drawn from a population, the resulting group becomes more representative of the population.", "id": 336, "score": 7.075, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [14], "q": "What mistake do people make about small samples?", "a": "They often assume that representativeness holds for small samples too, which understates how much variation is possible when few observations are involved.", "id": 337, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [15], "q": "What is an illusory correlation?", "a": "It is a relationship that appears to exist even though it does not exist or is much weaker than assumed.", "id": 338, "score": 5.075, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [15], "q": "What are stereotypes, and how do they shape attention?", "a": "Stereotypes are oversimplified generalizations about a group, often emphasizing negative characteristics. They direct attention toward behaviors that fit the expected description.", "id": 339, "score": 4.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [15], "q": "How are illusory correlations related to availability?", "a": "Stereotype-consistent behaviors received particular attention and are easier to bring to mind, and their availability is mistaken for evidence of a strong association.", "id": 340, "score": 4.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [16], "q": "What did Lord and colleagues (1979) do?", "a": "People who favored capital punishment and people who opposed it read the same article.", "id": 341, "note": "In the original study participants read two mixed-evidence studies on capital punishment, not the same article, and the result is usually described as biased assimilation and attitude polarization.", "score": 9.375, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [16], "q": "What did Lord and colleagues (1979) find?", "a": "Those in favor interpreted the article as favorable to their position, and those against interpreted it as favorable to theirs, so existing attitude influenced how the evidence was evaluated.", "id": 342, "score": 9.375, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [16], "q": "What is the myside bias?", "a": "It is the tendency to generate and evaluate evidence, and to test hypotheses, in ways biased toward one’s own opinions and attitudes.", "id": 343, "score": 9.075, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [17], "q": "What is confirmation bias?", "a": "It is the tendency to seek information that fits a hypothesis and overlook information that argues against it. Myside bias is one form of it.", "id": 344, "score": 7.075, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [17], "q": "How does the 2, 4, 6 task work?", "a": "Participants receive 2, 4, 6 as a sequence that fits a hidden rule, write their own sets of three numbers with reasons, receive feedback only on whether each fits the rule, and then propose the rule.", "id": 345, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [17], "q": "What is the actual rule in the 2, 4, 6 task, and what mistake is common?", "a": "The rule is three numbers in increasing order. The most common hypothesis is increasing intervals of two, and testing only sequences that satisfy it gives repeated positive feedback without distinguishing it from the broader rule.", "id": 346, "score": 6.375, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [18], "q": "What is utility?", "a": "Utility refers to outcomes that are desirable because they serve the person’s interests, expressing how beneficial an outcome is to the decision maker.", "id": 347, "score": 5.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [18], "q": "What is expected utility theory?", "a": "It assumes that people are rational and, with all relevant information, choose the alternative with maximum expected utility, combining the value of outcomes with their chances. The monetary version uses maximum expected monetary payoff.", "id": 348, "score": 5.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [19], "q": "Why does expected utility not fully describe what people choose?", "a": "People find value in things other than money, and many decisions fail to maximize the probability of the best outcome, so people are not utility-maximization machines.", "id": 349, "score": 1.0, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [19], "q": "What does casino gambling show?", "a": "People continue to choose an activity despite knowing that the odds are strongly against them, so decision behavior involves considerations beyond maximum expected monetary payoff.", "id": 350, "note": "Casino gambling shows that people do not maximize expected money. It does not by itself refute expected utility theory, because utility can include enjoyment of gambling.", "score": 1.0, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [19], "q": "What does expected utility theory offer for comparing alternatives?", "a": "It supplies specific procedures for determining the best choice according to expected benefit, a consistent basis for comparing alternatives when their outcomes and probabilities are available.", "id": 351, "score": 1.0, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [20], "q": "What are the two bowls in the jellybean problem?", "a": "Participants earn one dollar when they draw a red jellybean and choose between a bowl with 1 red bean out of 10 and a bowl with 7 red beans out of 100.", "id": 352, "score": 7.7, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [20], "q": "Which bowl do people choose, and what does it show?", "a": "Most choose the 7-out-of-100 bowl even though the chance is 7 percent against 10 percent. The larger number of favorable items draws attention away from the denominator, so the decision depends on considerations other than actual probabilities.", "id": 353, "note": "The slide says most participants choose the 7-out-of-100 bowl. I could not verify that a majority chose it in the original finding.", "score": 7.0, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [21], "q": "What happened to travel after September 11?", "a": "Air travel decreased and driving increased, and the probability of dying in a car accident is much greater than while flying.", "id": 354, "score": 1.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [21], "q": "What does the shift from flying to driving after September 11 show about risk decisions?", "a": "Avoiding a feared event increased exposure to a more likely danger. The reported number of Americans who died on the road while avoiding flying exceeded the total number of passengers killed on the four hijacked flights.", "id": 355, "score": 1.375, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [22], "q": "What is the convoy dilemma?", "a": "A convoy of food trucks travels to a refugee camp during a famine, and rerouting saves 1,000 people at a second camp but 100 people in the first camp die because the trucks no longer arrive.", "id": 356, "score": 9.7, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [22], "q": "What did Ritov and Baron (1999) find in the convoy dilemma?", "a": "63 percent did not choose to reroute, even though rerouting has the better net count, 1,000 − 100 = 900. Some would keep the original route even if only one person at the first camp would die.", "id": 357, "score": 10.0, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [23], "q": "What is the Sacred Value Protection Model of Tetlock, Kristel, Elson, Green and Lerner (2000)?", "a": "It proposes that people want to protect what they hold sacred, and that sacred values are compartmentalized separately from secular values.", "id": 358, "score": 10.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [23], "q": "What are taboo and tragic tradeoffs?", "a": "A taboo tradeoff intermingles sacred and secular domains and can provoke moral outrage. A tragic tradeoff compares two sacred values with one another, and people are less morally outraged by it.", "id": 359, "score": 10.2, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [24], "q": "What are the taboo and tragic scenarios with Johnny?", "a": "In the taboo scenario, Robert can save Johnny, a five-year-old needing a liver transplant that costs one million dollars, or use the funds for equipment and salaries. In the tragic scenario, two children need a liver but only one is available.", "id": 360, "score": 7.45, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [25], "q": "What did Tetlock and colleagues (2000) find about moral outrage?", "a": "Under the taboo tradeoff, not saving Johnny produced much greater outrage than saving him, and under the tragic tradeoff outrage was similar whether Johnny was saved or not.", "id": 361, "score": 10.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [26], "q": "Who participated in Ginges, Atran, Medin and Shikaki (2007), and what did they offer?", "a": "They interviewed 601 Israeli settlers, 535 Palestinian refugees and 719 Palestinian students, and offered three types of tradeoff deals as possible solutions.", "id": 362, "score": 6.0, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [27], "q": "What are the taboo, Taboo+ and symbolic deals in Ginges, Atran, Medin and Shikaki (2007)?", "a": "The taboo deal asks Palestinians to recognize the sacred and historic right of the Jewish people to Israel, with two states. Taboo+ adds one billion dollars a year for ten years from Israel. The symbolic version adds recognition of the Palestinians’ right to their own state and an apology.", "id": 363, "score": 9.125, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [28], "q": "What are moral absolutists?", "a": "They treat an issue under dispute as a sacred value and consider a compromise unacceptable regardless of how much benefit it could produce. Non-absolutists also have strong preferences but do not treat the issues as sacred.", "id": 364, "score": 9.2, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [28], "q": "How common were sacred values in Ginges, Atran, Medin and Shikaki (2007)?", "a": "About 46 percent of the settlers held that they should never give up part of the Land of Israel, and about 54 percent of the Palestinian students treated both the right of return and Jerusalem as sacred.", "id": 365, "score": 9.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [29], "q": "How did a material incentive affect absolutists and non-absolutists in Ginges, Atran, Medin and Shikaki (2007)?", "a": "In Ginges, Atran, Medin and Shikaki (2007), for absolutists, adding money in Taboo+ increased anger, disgust and support for violence. For non-absolutists, it reduced them.", "id": 366, "score": 8.125, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [29], "q": "How did the symbolic offer compare in Ginges, Atran, Medin and Shikaki (2007)?", "a": "In Ginges, Atran, Medin and Shikaki (2007), symbolic recognition was associated with lower anger or disgust and lower support for violence, so material benefit and symbolic reciprocity are different.", "id": 367, "score": 8.125, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [29], "q": "What does the comparison of material benefit and symbolic reciprocity in Ginges, Atran, Medin and Shikaki (2007) show?", "a": "In Ginges, Atran, Medin and Shikaki (2007), increasing an economic incentive is not automatically an improvement in a negotiation over sacred concerns. What the offer asks people to exchange, and how it treats their commitments, affects the emotional and behavioral judgments they report.", "id": 368, "score": 8.125, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [30], "q": "What are incentives and disincentives in negotiations over sacred values?", "a": "An incentive offers a benefit for agreement, and a disincentive imposes a cost for refusing. Economic funds are an incentive and economic sanctions are a disincentive.", "id": 369, "score": 5.0, "tier": "low"}, {"module": 12, "kind": "slide", "slides": [30], "q": "What did Dehghani, Atran and colleagues (2010) and Dehghani, Iliev and colleagues (2009) investigate?", "a": "They investigated whether people who treated Iran’s nuclear program as a sacred value would be amenable to material benefits or costs in exchange for compromise.", "id": 370, "score": 6.0, "tier": "mid"}, {"module": 12, "kind": "slide", "slides": [31], "q": "How was a sacred value classified in the study by Dehghani and colleagues (2009, 2010)?", "a": "In Dehghani and colleagues (2009, 2010), the measure, based on Baron and Spranca (1997), classified participants as holding a sacred value if they said giving up the program should not be done no matter how great the consequences.", "id": 371, "score": 10.0, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [31], "q": "How big was the study by Dehghani and colleagues (2009, 2010), and how common were sacred values?", "a": "In Dehghani and colleagues (2009, 2010), there were 1,997 Iranian participants, in Farsi. About 14 percent for nuclear energy and 13 percent for nuclear weapons chose the sacred-value response.", "id": 372, "score": 10.0, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [32], "q": "What was the design of the experiment by Dehghani and colleagues (2009, 2010)?", "a": "Dehghani and colleagues (2009, 2010) used a 2 × 3 design, with the nuclear program being energy or weapons and the deal being Taboo, Taboo+ or Taboo−, giving six conditions.", "id": 373, "score": 8.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [32], "q": "What are Taboo, Taboo+ and Taboo− in Dehghani and colleagues (2009, 2010)?", "a": "In Dehghani and colleagues (2009, 2010), Taboo has Iran give up its program and surrender facilities to the United Nations in return for Israel doing the same. Taboo+ adds 40 billion dollars from the United Nations to Iran, and Taboo− adds the threat of additional sanctions if Iran refuses.", "id": 374, "score": 8.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [33], "q": "What happened for participants with a sacred value about nuclear energy in Dehghani and colleagues (2009, 2010)?", "a": "In Dehghani and colleagues (2009, 2010), approval was lower with the financial incentive and with sanctions than with the baseline, and anticipated anger was highest with the financial incentive and elevated with sanctions.", "id": 375, "score": 8.5, "tier": "high"}, {"module": 12, "kind": "slide", "slides": [33], "q": "How did participants without a sacred value respond in Dehghani and colleagues (2009, 2010)?", "a": "In Dehghani and colleagues (2009, 2010), they had much higher approval and lower anger across the energy conditions, with little variation between the baseline, incentive and sanctions versions.", "id": 376, "score": 8.5, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [3, 4, 5], "q": "How do induction and heuristics differ as ways of reaching a judgment?", "a": "Induction draws a probable conclusion from observed evidence, while heuristics are shortcuts that use past experience and cues like availability or similarity, and are likely correct but not foolproof.", "id": 377, "score": 4.8, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [6, 7, 8, 9, 10, 11], "q": "How do the availability and representativeness heuristics each lead to errors?", "a": "Availability substitutes ease of remembering for probability, as in the r-words and causes of death. Representativeness substitutes resemblance for probability, ignoring base rates in Robert and Jack and the conjunction rule in Linda.", "id": 378, "score": 7.408, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [9, 10], "q": "Why do Robert and Jack show the same underlying error?", "a": "In both, a description that resembles a category displaces the background frequencies of the categories, which is base-rate neglect.", "id": 379, "score": 7.175, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [9, 10, 11], "q": "How do the Linda problem and the base-rate problems both reflect representativeness?", "a": "Each response follows how well a description fits a category, and not the probability relationship, the nested sets in Linda and the group composition in Jack.", "id": 380, "score": 7.383, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [11, 12, 13, 14], "q": "How are the conjunction rule and the law of large numbers different kinds of probability principle?", "a": "The conjunction rule concerns nested sets, since adding a condition cannot raise probability, while the law of large numbers concerns sample size and representativeness.", "id": 381, "score": 7.662, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [12, 13, 14], "q": "How do the hospital problem and small samples connect to representativeness?", "a": "Answering about the same ignores the number of births behind each percentage, and people often assume small samples are representative, but small samples vary more and produce extreme proportions more often.", "id": 382, "score": 7.567, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [6, 15], "q": "How do availability and illusory correlation connect?", "a": "Stereotype-consistent behaviors get attention and are easier to bring to mind, and that availability is mistaken for strong evidence of association.", "id": 383, "score": 6.475, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [16, 17], "q": "How do myside bias and confirmation bias differ?", "a": "Confirmation bias is the broad tendency to seek fitting information and overlook the contrary, and myside bias is one form, applied to one’s own opinions and attitudes.", "id": 384, "score": 8.475, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [16, 17], "q": "How do Lord and colleagues (1979) and the 2, 4, 6 task both show biased evidence use?", "a": "In Lord and colleagues, the same article was read as favorable to each side. In the 2, 4, 6 task, testing only sequences that fit the hypothesis gives repeated positive feedback and leaves the narrow hypothesis intact.", "id": 385, "score": 9.475, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [17], "q": "Why would testing for disconfirmation help in the 2, 4, 6 task?", "a": "Trying sequences that violate the hypothesis tests its boundaries, while confirming triples leave the narrower belief intact.", "id": 386, "score": 6.875, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [18, 19, 20], "q": "How do expected utility theory and the real choices of people differ?", "a": "The theory says people choose the maximum expected utility, but people value things beyond money and gamble against the odds, so behavior departs from it.", "id": 387, "score": 6.4, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [12, 20], "q": "How do the jellybean problem and the hospital problem both show people overlooking part of the information?", "a": "In the jellybean problem the larger number of red beans drew attention away from the denominator, and in the hospital problem the answer about the same left out how many births were behind each day’s percentage.", "id": 388, "score": 6.9, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [8, 21], "q": "What do the post-September 11 travel example and the causes-of-death comparisons each show about how decisions depart from actual probability?", "a": "In the causes-of-death comparisons, distinctive coverage made an unusual cause more available than a more likely one. After September 11, the emotional impact of the attacks guided travel choices toward the more probable danger of the road.", "id": 389, "score": 3.475, "tier": "low"}, {"module": 12, "kind": "relate", "slides": [18, 22], "q": "How do the convoy dilemma of Ritov and Baron (1999) and expected utility show different ways of evaluating outcomes?", "a": "In Ritov and Baron (1999), counting lives saved says reroute, but 63 percent did not, and reluctance to cause a loss can outweigh the larger number saved.", "id": 390, "score": 9.65, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [23, 24], "q": "How do taboo and tragic tradeoffs differ in what is being compared?", "a": "A taboo tradeoff compares a sacred value with a secular benefit, while a tragic tradeoff compares two sacred values.", "id": 391, "score": 9.45, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [24, 25], "q": "What was the interaction in the Johnny results of Tetlock and colleagues (2000)?", "a": "Outrage depended on the outcome only in the taboo condition, where not saving Johnny was far worse, and was similar for both outcomes in the tragic condition.", "id": 392, "score": 10.45, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [22, 23, 24, 25], "q": "How do the Johnny scenarios of Tetlock and colleagues (2000) and the convoy dilemma of Ritov and Baron (1999) both show limits of counting outcomes?", "a": "In the Johnny scenarios outrage depended on the type of tradeoff, and in the convoy dilemma reluctance to cause a loss can outweigh the larger number saved, so in both the responses were not a simple numerical comparison.", "id": 393, "score": 10.675, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [23, 28, 29], "q": "Why does a material incentive backfire for moral absolutists but not for non-absolutists in Ginges, Atran, Medin and Shikaki (2007)?", "a": "For absolutists the issue is sacred, so money makes an exchange they already treat as sacred more objectionable, raising anger, disgust and support for violence. For non-absolutists it lowers them.", "id": 394, "score": 10.55, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [27, 29], "q": "Why does symbolic recognition work differently from money in Ginges, Atran, Medin and Shikaki (2007)?", "a": "It addresses the status of the group’s sacred claim, so it was associated with lower anger and lower support for violence, while money engages a material exchange.", "id": 395, "score": 9.425, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [26, 27, 28, 31, 32, 33], "q": "How do Dehghani, Atran and colleagues (2010) and Dehghani, Iliev and colleagues (2009) share a design idea with Ginges, Atran, Medin and Shikaki (2007)?", "a": "Both compare a taboo deal with versions that add material benefit or cost, and both separate participants who hold the issue sacred from those who do not.", "id": 396, "score": 9.942, "tier": "high"}, {"module": 12, "kind": "relate", "slides": [30, 33], "q": "Why can sanctions and incentives both fail when a value is sacred in Dehghani and colleagues (2009, 2010)?", "a": "Both try to change the material consequences, and for participants with a sacred value about nuclear energy, approval was lower and anticipated anger higher with the incentive and with sanctions than with the baseline.", "id": 397, "score": 8.5, "tier": "mid"}, {"module": 12, "kind": "relate", "slides": [18, 28, 29], "q": "How does the sacred-value account differ from expected utility theory in what a larger benefit does?", "a": "Expected utility theory combines the value of outcomes with their chances, so a larger benefit should raise the expected utility. For moral absolutists in Ginges, Atran, Medin and Shikaki (2007), adding money increased anger, disgust and support for violence.", "id": 398, "score": 8.317, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [2], "q": "How do emotions take part in decision making?", "a": "Emotions take part in decision making and do not only get in its way. People with damage to an area of their prefrontal cortex who have flattened emotions have impaired decision making.", "id": 399, "score": 4.375, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [2], "q": "How does anxiety affect decisions?", "a": "Anxious people tend to avoid decisions that could potentially lead to large negative consequences, which is risk avoidance, even when the option might turn out well.", "id": 400, "score": 4.375, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [2], "q": "How does optimism affect decisions?", "a": "Optimistic people are more likely to ignore negative information and focus on positive information, and too much optimism can lead to poor decisions.", "id": 401, "score": 4.375, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [3], "q": "What are expected emotions?", "a": "They are emotions that people predict they will feel concerning an outcome, and they guide which option the person is willing to take.", "id": 402, "score": 5.075, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [3], "q": "How are expected emotions related to risk aversion?", "a": "Expected emotions are one determinant of risk aversion, the tendency to avoid taking risks. A person who expects to feel very bad after a loss is less willing to accept a chance of it.", "id": 403, "score": 4.375, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [3], "q": "How do people mispredict their emotions about losses and gains?", "a": "People believe a particular loss will have a greater impact than a gain of the same size, which increases risk aversion.", "id": 404, "score": 4.375, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [4], "q": "What was the procedure in Kermer and colleagues (2006)?", "a": "Participants were given $5 and told that a coin flip would either win them another $5 or lose them $3, and they rated happiness beforehand as a baseline.", "id": 405, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [4], "q": "What did participants expect in Kermer and colleagues (2006)?", "a": "They expected losing $3 to lower happiness by about 4 points and winning $5 to raise it by about 2, so the expected loss was about twice the expected gain.", "id": 406, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [4], "q": "What actually happened in Kermer and colleagues (2006), and why?", "a": "The actual drop from losing was only about 1 point and the rise from winning about 1.2. People overestimate the negative feeling because coping mechanisms soften a loss, and they do not consider them when predicting.", "id": 407, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [5], "q": "What are incidental emotions?", "a": "They are emotions not specifically related to decision making, related to general disposition, a recent experience or the surroundings.", "id": 408, "score": 9.075, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [5], "q": "What did Simonsohn (2007) find about admissions decisions?", "a": "Applicants’ academic attributes were weighted more heavily on cloudy days than on sunny days, although the weather had nothing to do with the applicants.", "id": 409, "score": 9.375, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [5], "q": "What did Simonsohn (2009) find about campus visits?", "a": "Prospective students visiting a highly rated university were more likely to enroll if they had visited on a cloudy day.", "id": 410, "score": 9.375, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [6], "q": "What was the procedure in Lerner and colleagues (2004)?", "a": "Participants viewed a sad clip of a person dying, a disgust clip of a person using a dirty toilet, or a neutral clip of fish at the Great Barrier Reef, then set a price to sell and a price to buy a set of highlighters.", "id": 411, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [6], "q": "What did Lerner and colleagues (2004) find for selling prices?", "a": "Neutral asked about $4.50, disgust about $2.70 and sad about $3.00.", "id": 412, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [6], "q": "What did Lerner and colleagues (2004) find for buying prices?", "a": "Neutral offered about $3.50, disgust about $3.00 and sad about $4.50. Disgust lowered both prices, while sadness lowered the selling price and raised the buying price.", "id": 413, "score": 9.0, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [7], "q": "How does the context of a decision change a physician’s choice?", "a": "The cesarean test case was always the same. In the control context it was presented first, in the serious context it was preceded by four cases with serious complications, and in the not serious context it was preceded by four fairly routine cases. Significantly more doctors recommended cesarean after reading non-serious cases first.", "id": 414, "score": 6.0, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [8], "q": "How do opt-in and opt-out procedures differ in organ donation consent?", "a": "Under opt-in a person must take an active step to be a donor and consent is below 28 percent. Under opt-out a person is a donor unless they request not to be, and consent is over 99 percent.", "id": 415, "note": "Not every opt-out country exceeds 99 percent consent. Reported effective consent in opt-out countries ranges from about 86 percent to about 99.98 percent.", "score": 7.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [8], "q": "What is the status quo bias?", "a": "It is the tendency to do nothing when faced with a difficult decision, so doing nothing leaves a person a non-donor under opt-in and a donor under opt-out.", "id": 416, "note": "The usual definition of status quo bias is a preference for the current state or default, and doing nothing is the mechanism, not the definition.", "score": 7.7, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [8], "q": "What choice does the short story The International Community present?", "a": "A chicken, a duck, a turkey, a pheasant, a quail and a partridge were summoned and traveled together to the summit, where the king’s chef told them he had called them so they could tell him what sauce they would like to be eaten with. When one bird said it did not want to be eaten at all, the chef said that was out of the question, so the only choice offered was which sauce, which is a choice of the same kind as a default.", "id": 417, "score": 7.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [9], "q": "What is the framing effect?", "a": "It occurs when decisions are influenced by how a decision is stated, such as what might be gained or lost, while the facts of the choice stay the same.", "id": 418, "score": 9.825, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [9], "q": "What did Tversky and Kahneman (1981) find about gain and loss framing?", "a": "When situations are framed as gains, people tend toward a risk-aversion strategy and prefer the sure option. When framed as losses, they tend toward a risk-taking strategy and prefer the gamble.", "id": 419, "score": 10.125, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [9], "q": "What are risk-aversion and risk-taking strategies?", "a": "A risk-aversion strategy avoids an uncertain outcome in favor of a certain one, and a risk-taking strategy accepts an uncertain outcome in the hope of avoiding a certain loss.", "id": 420, "score": 9.825, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [11], "q": "What are the programs in the gain frame of the disease problem in Tversky and Kahneman (1981)?", "a": "In Tversky and Kahneman (1981), a disease is expected to kill 600 people. Program A saves 200 for certain, and Program B has a 1/3 probability that 600 are saved and a 2/3 probability that none are saved.", "id": 421, "score": 8.75, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [11], "q": "What did people choose in the gain frame in Tversky and Kahneman (1981)?", "a": "In Tversky and Kahneman (1981), 72 percent chose Program A, the sure option, and 28 percent chose Program B, which fits risk aversion.", "id": 422, "score": 8.75, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [12], "q": "What are the programs in the loss frame of the disease problem in Tversky and Kahneman (1981)?", "a": "In Tversky and Kahneman (1981), Program C means 400 people die for certain, and Program D has a 1/3 probability that no one dies and a 2/3 probability that 600 die.", "id": 423, "score": 8.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [12], "q": "What did people choose in the loss frame in Tversky and Kahneman (1981), and why is it the framing effect?", "a": "In Tversky and Kahneman (1981), 78 percent chose Program D and 22 percent chose Program C. Program C has the same outcome as A and Program D is the same gamble as B, so only the wording changed and most people switched to the gamble.", "id": 424, "score": 8.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [13], "q": "What is neuroeconomics?", "a": "It combines research from psychology, neuroscience and economics, and one finding is that decisions are influenced by emotions associated with activity in specific brain areas.", "id": 425, "score": 4.7, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [14], "q": "How does the ultimatum game work in Sanfey and colleagues (2003)?", "a": "A proposer gets $10 and offers a split to the responder, who can accept, so the money is divided as offered, or reject, so neither player receives anything.", "id": 426, "score": 6.0, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [14], "q": "What is the rational decision for the responder according to utility theory?", "a": "To accept any offer, because even $1 is worth more than the nothing that comes from rejecting.", "id": 427, "score": 5.0, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [15], "q": "What were the offers and acceptance rates in Sanfey and colleagues (2003)?", "a": "Participants played 20 games, 10 with humans and 10 with computers. $5–$5 and $7–$3 offers were accepted at about 100 and 95 percent for both partners, while $8–$2 was accepted about 53 percent from a human and 85 from a computer, and $9–$1 about 37 and 68 percent.", "id": 428, "score": 8.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [15], "q": "Why were unfair offers rejected more often from humans in Sanfey and colleagues (2003)?", "a": "In Sanfey and colleagues (2003), participants often rejected low offers because they became angry that the offers were unfair, and they were less angry with an unfair computer.", "id": 429, "score": 8.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [15], "q": "What did brain activity show in Sanfey and colleagues (2003)?", "a": "Participants with more activation of the right anterior insula, an area connected with emotional states, were more likely to reject more offers, which meant getting nothing.", "id": 430, "score": 8.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [16], "q": "What is deductive reasoning?", "a": "It is determining whether a conclusion logically follows from premises, which are the statements the reasoning starts from.", "id": 431, "score": 6.2, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [16], "q": "What is a syllogism, and what is a categorical syllogism?", "a": "A syllogism, introduced by Aristotle, has two premises and a conclusion. A categorical syllogism describes the relation between two categories using all, no or some.", "id": 432, "score": 5.5, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [16], "q": "How does the birds-and-animals syllogism work?", "a": "All birds are animals, all animals eat food, therefore all birds eat food. Birds fall inside animals and animals fall inside things that eat food.", "id": 433, "score": 5.5, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [17], "q": "What does it mean for a syllogism to be valid?", "a": "Its conclusion follows logically from its two premises, so if the premises of a valid syllogism are true then the conclusion must be true.", "id": 434, "score": 4.75, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [17], "q": "How are validity and truth different?", "a": "Validity depends on the form of the reasoning and truth on whether statements match the world. All birds are animals, all animals have four legs, all birds have four legs is valid but its conclusion is false because the second premise is false.", "id": 435, "score": 4.75, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [18], "q": "How can a syllogism be invalid although every statement sounds reasonable?", "a": "In All of the students are tired, some tired people are irritable, some of the students are irritable, every statement sounds reasonable but the conclusion does not follow from the premises.", "id": 436, "score": 7.375, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [18], "q": "What is belief bias?", "a": "It is the tendency to think a syllogism is valid if its conclusion is believable. 71 percent of participants judged invalid syllogisms with believable conclusions as valid.", "id": 437, "score": 8.075, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [19], "q": "How can imagining the situation help solve reasoning problems?", "a": "There is no easy method for judging whether a syllogism is valid, and one way is to picture the situation the statements describe. Most people solve the pool table problem by imagining how the balls are arranged.", "id": 438, "score": 1.0, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [19], "q": "What is the answer to the pool table problem?", "a": "The cue ball is to the left of the line of sight. With the red ball blocking the black ball, looking past it toward the black ball puts the cue ball off to the left.", "id": 439, "score": 1.7, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [20], "q": "What is a mental model in Johnson-Laird (1999)?", "a": "A mental model is a specific situation represented in a person’s mind that can be used to help determine the validity of syllogisms.", "id": 440, "score": 8.075, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [20], "q": "What are the steps of the mental model approach?", "a": "Create a model of the situation, generate tentative conclusions about it, look for exceptions to falsify the model, and determine validity from whether an exception was found.", "id": 441, "score": 7.075, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [20], "q": "When is a conclusion valid in the mental model approach?", "a": "A conclusion is valid only if it cannot be refuted by any model of the premises. If even one model fits the premises but not the conclusion, the conclusion does not follow.", "id": 442, "score": 6.375, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [21], "q": "What is the form of a conditional syllogism?", "a": "The first premise is of the form If p, then q, where p is a condition and q is what follows. The four types differ in the second premise, p, not p, q or not q.", "id": 443, "score": 4.7, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [21], "q": "How many conditional syllogisms are valid?", "a": "Two of the four are valid and two are not.", "id": 444, "score": 4.0, "tier": "low"}, {"module": 13, "kind": "slide", "slides": [22], "q": "What is modus ponens, and how often was it judged correctly?", "a": "If p then q, p, therefore q, as in If I study I’ll get a good grade, I studied, therefore I’ll get a good grade. It is valid and 97 percent judged it correctly.", "id": 445, "score": 8.5, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [23], "q": "What is modus tollens, and how often was it judged correctly?", "a": "If p then q, not q, therefore not p, as in I didn’t get a good grade, therefore I didn’t study. It is valid, but only 60 percent judged it correctly.", "id": 446, "score": 8.125, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [24], "q": "Why is conditional syllogism 3 not valid?", "a": "If p then q, q, therefore p does not follow, because the first premise does not say studying is the only way to get a good grade. Only 40 percent judged it correctly.", "id": 447, "score": 7.75, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [24], "q": "How does the same form with Tucson and Arizona show it?", "a": "If I live in Tucson then I live in Arizona, I live in Arizona, therefore I live in Tucson fails, because a person can live in Arizona without living in Tucson.", "id": 448, "score": 7.75, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [25], "q": "Why is conditional syllogism 4 not valid?", "a": "If p then q, not p, therefore not q does not follow, because the first premise says nothing about what happens when someone does not study. Only 40 percent judged it correctly.", "id": 449, "score": 8.125, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [25], "q": "How did people do across the four conditional syllogisms?", "a": "The two valid ones were judged correctly at 97 and 60 percent, and the two invalid ones at 40 percent each, so both valid types were judged correctly more often.", "id": 450, "score": 8.125, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [26], "q": "What is the Wason four-card problem?", "a": "Four cards read E, K, 4 and 7, and the task is to find the minimum number to turn over to test the rule if there is a vowel on one side, then there is an even number on the other.", "id": 451, "score": 7.7, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [26], "q": "Which cards should be turned over, and what do people choose?", "a": "The E and the 7. 46 percent chose the 4, which is an error, and only 7 percent chose the 7, which is correct.", "id": 452, "note": "Wason’s percentages are for combinations of cards. About 46 percent chose E and 4 and about 7 percent chose E and 7, so only 7 percent chose the 7 understates how many selected it.", "score": 7.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [26], "q": "Why is turning over the 7 a real test of the rule?", "a": "A 7 with a vowel on its other side would break the rule, while a 4 cannot break the rule whatever is on its back.", "id": 453, "score": 7.0, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [27], "q": "What is the falsification principle?", "a": "To test a rule you must look for situations that falsify it, meaning prove it false. Most participants fail to do this.", "id": 454, "score": 8.45, "tier": "high"}, {"module": 13, "kind": "slide", "slides": [27], "q": "How does the concrete beer version change performance?", "a": "With the rule If drinking beer, then 21 years old and cards Beer, Soda, 16 years old and 21 years old, 73 percent answered correctly. The correct cards are beer and 16 years old.", "id": 455, "score": 7.75, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [28], "q": "What is a permission schema?", "a": "It is the idea that if A is satisfied, B can be carried out, a familiar pattern of rule that grants permission once a condition is met.", "id": 456, "score": 6.7, "tier": "mid"}, {"module": 13, "kind": "slide", "slides": [28], "q": "Why does a permission schema make the card problem easier?", "a": "People are familiar with permission rules such as a drinking age, so a rule in a familiar setting is easier to reason about than an abstract one. Familiarity alone is not what matters.", "id": 457, "score": 6.0, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [3, 4], "q": "How do expected emotions and actual emotions differ in Kermer and colleagues (2006), and what does this mean for decisions?", "a": "People expected a loss to hurt about twice as much as a gain helps, but the actual drop was only about 1 point, so risk aversion partly rests on overestimated negative feelings.", "id": 458, "score": 8.775, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [3, 5, 6], "q": "How do expected emotions and incidental emotions differ?", "a": "Expected emotions are predictions about an outcome of the decision, while incidental emotions are not specifically related to the decision, such as weather or mood from an unrelated clip.", "id": 459, "score": 8.292, "tier": "mid"}, {"module": 13, "kind": "relate", "slides": [5, 6], "q": "How do Simonsohn (2007, 2009) and Lerner and colleagues (2004) both show incidental emotions affect decisions?", "a": "In Simonsohn (2007, 2009), weather changed how admissions attributes were weighted and enrollment, and in Lerner and colleagues (2004) mood from film clips changed buying and selling prices, though neither was related to the choice.", "id": 460, "score": 9.8, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [7, 8], "q": "How do context in the cesarean case and presentation in organ donation show that decisions depend on more than the options?", "a": "The same test case drew different recommendations after different earlier cases, and the same choice drew over 99 percent versus below 28 percent consent depending on opt-out or opt-in.", "id": 461, "score": 7.3, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [8], "q": "How does status quo bias explain the opt-in and opt-out difference?", "a": "Many people do nothing either way, so the default determines whether they end up donors.", "id": 462, "score": 7.5, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [9, 11, 12], "q": "How do the gain and loss frames of the disease problem in Tversky and Kahneman (1981) show the same facts producing opposite choices?", "a": "In Tversky and Kahneman (1981), Program A and C have the same outcome and B and D the same gamble, but 72 percent chose the sure option in gains and 78 percent chose the gamble in losses.", "id": 463, "score": 10.158, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [3, 9], "q": "How do expected emotions and the framing effect of Tversky and Kahneman (1981) each involve gains and losses?", "a": "People expect a loss to have a greater impact than a gain of the same size, which increases risk aversion. In the framing effect, gain wording leads to the sure option and loss wording leads to the gamble, a risk-taking strategy that accepts uncertainty in the hope of avoiding a certain loss.", "id": 464, "score": 9.675, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [14, 15], "q": "How does the ultimatum game of Sanfey and colleagues (2003) contrast utility theory with real behavior?", "a": "Utility theory says accept any offer, but participants rejected low offers when angered by unfairness, giving up money.", "id": 465, "score": 8.1, "tier": "mid"}, {"module": 13, "kind": "relate", "slides": [13, 15], "q": "What does the anterior insula result in Sanfey and colleagues (2003) add to the human versus computer difference?", "a": "Anger at unfair offers explains why they were rejected more often from humans than from computers. Separately, more right anterior insula activation, an area connected with emotional states, went with more rejections.", "id": 466, "score": 7.9, "tier": "mid"}, {"module": 13, "kind": "relate", "slides": [4, 13, 15], "q": "How do the ultimatum game and Kermer and colleagues (2006) each show emotions shaping choices about money?", "a": "In the ultimatum game, anger at unfair offers, linked to anterior insula activation, led participants to give up money by rejecting them. In Kermer and colleagues (2006), people expected losing money to hurt about twice as much as winning helped, and overestimated the negative feeling.", "id": 467, "score": 8.833, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [16, 17, 18], "q": "How do validity and truth relate for a syllogism?", "a": "A syllogism can be valid with true or false premises and invalid even when every statement seems reasonable, so validity does not guarantee a true conclusion and believability does not guarantee validity.", "id": 468, "score": 7.275, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [17, 18], "q": "How does belief bias show truth interfering with judging validity?", "a": "A believable conclusion led 71 percent to accept invalid syllogisms as valid.", "id": 469, "score": 7.35, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [19, 20], "q": "How does the mental model approach explain why finding an exception matters?", "a": "A conclusion is valid only if no model of the premises refutes it, so one exception shows it does not follow.", "id": 470, "score": 5.8, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [20, 26, 27], "q": "How are the mental model approach and the falsification principle similar?", "a": "Both say reasoning is tested by looking for cases that would make the conclusion or rule false, and not by confirming cases.", "id": 471, "score": 7.967, "tier": "mid"}, {"module": 13, "kind": "relate", "slides": [22, 23], "q": "Why are modus ponens and modus tollens both valid, yet judged differently?", "a": "Both follow from If p then q, but 97 percent judged modus ponens correctly and only 60 percent judged modus tollens, which reasons from a result that did not happen back to a condition that did not.", "id": 472, "score": 8.925, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [24, 25], "q": "Why are syllogisms 3 and 4 invalid, and what do they have in common?", "a": "Each assumes the condition is the only route to the result, but the first premise only says what happens when p holds, so q can occur without p.", "id": 473, "score": 8.55, "tier": "high"}, {"module": 13, "kind": "relate", "slides": [26, 27, 28], "q": "Why did the 7 card in the abstract Wason task rarely get chosen, while the concrete version improved?", "a": "Most participants fail to look for falsifying cards and choose the 4, and a familiar permission rule such as a drinking age makes the falsifying cards clearer.", "id": 474, "score": 7.917, "tier": "mid"}, {"module": 13, "kind": "relate", "slides": [27, 28], "q": "How are permission schemas related to the concrete versions of conditional reasoning?", "a": "A permission schema supplies a familiar pattern, if the condition is satisfied the action is allowed, which makes the concrete version easier than abstract letters and numbers.", "id": 475, "score": 7.9, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [16, 21], "q": "How does a categorical syllogism differ from a conditional syllogism?", "a": "A categorical syllogism describes the relation between two categories using all, no or some. A conditional syllogism has a first premise of the form If p, then q, and its four types differ in the second premise, which states p, not p, q or not q.", "id": 476, "score": 5.7, "tier": "low"}, {"module": 13, "kind": "relate", "slides": [2, 6, 15, 18], "q": "How do emotion and reasoning errors each lead decisions away from what utility theory predicts?", "a": "Emotions such as anger, anxiety or sadness change choices, and reasoning biases such as belief bias reduce logical judgments, so neither follows a purely rational standard.", "id": 477, "score": 7.975, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [1], "q": "What is the phonological similarity effect?", "a": "Lists of similar-sounding items are recalled worse than lists of different-sounding items, even when the items are only read silently. Acoustic similarity effect is arguably the better name.", "id": 478, "score": 7.075, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [1], "q": "Why does the phonological similarity effect show a speech-based code?", "a": "People recode what they see into a speech-based form. A purely visual code would cause mix-ups between look-alikes such as E and F instead.", "id": 479, "score": 6.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [1], "q": "How does the phonological loop explain the effect, and what does articulatory suppression do?", "a": "The loop has a phonological store and an articulatory control process that converts visual input to speech and refreshes traces. Articulatory suppression occupies that process, and with visually presented lists the similarity cost disappears.", "id": 480, "score": 6.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [2], "q": "What is a word’s neighborhood?", "a": "It is the set of words that differ from it by one letter, orthographic, or one sound, phonological. Cat is a large neighborhood word and hippopotamus a small neighborhood word.", "id": 481, "score": 8.7, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [2], "q": "What did Roodenrys et al. (2002) find?", "a": "Large neighborhood words are recalled better in short-term memory tasks, so long-term memory knowledge of words helps short-term recall.", "id": 482, "score": 9.0, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [2], "q": "Why is memory span not a pure measure of short-term capacity?", "a": "Because long-term memory knowledge of words affects short-term recall, so span reflects more than short-term capacity.", "id": 483, "score": 8.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [3], "q": "What is the Brown–Peterson task?", "a": "People study consonants and then do a distractor task, counting backwards, that blocks rehearsal. The longer the distraction, the worse the recall.", "id": 484, "score": 9.075, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [3], "q": "What did Peterson and Peterson (1959) conclude?", "a": "Because counting is so unlike remembering letters, they judged interference an unlikely cause and concluded that short-term memory loses information through decay unless it is rehearsed.", "id": 485, "flag": "The short-term memory slides treat the Brown–Peterson pattern as evidence of proactive interference, while this slide gives decay as the conclusion of Peterson and Peterson (1959) and cites Keppel and Underwood (1962) for an alternative. The two sets of slides take different views of the same task.", "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [3], "q": "What view did the conclusion of Peterson and Peterson (1959) challenge?", "a": "It challenged the view, following McGeoch’s (1932) critique, that forgetting is due to interference. Decay is the researchers’ conclusion, and Keppel and Underwood (1962) are cited for an alternative.", "id": 486, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [4], "q": "What is the modality effect?", "a": "Memory is better for the last one or two items of a list when it is heard than when it is read silently, and lip-read or silently mouthed lists show it too.", "id": 487, "score": 8.7, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [4], "q": "How did the modality effect influence ideas about sensory memory?", "a": "It strongly influenced ideas about sensory memory, a back-up store of raw, unanalyzed sensory input.", "id": 488, "score": 8.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [4], "q": "What explanation does Neath and Surprenant (2003) favor?", "a": "Hearing adds extra information about how the list sounds, which helps the final items.", "id": 489, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [5], "q": "What did Sperling (1960) argue about the limit on reporting a brief display?", "a": "That the limit comes from recall and not from perception.", "id": 490, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [5], "q": "What does partial report show in Sperling (1960)?", "a": "In Sperling (1960), a cue right after the display lets observers report the cued part almost perfectly, so a sensory, iconic, store briefly held nearly all of it.", "id": 491, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [5], "q": "What is the real limit on reporting a brief display in Sperling’s (1960) work?", "a": "The time needed to report. If the cue is delayed, performance falls toward the usual limit, because the store is very short-lived.", "id": 492, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [6], "q": "What is the position error effect?", "a": "Items are usually recalled in the correct position, and when they are not, the errors are systematic, with the item landing in an adjacent position.", "id": 493, "score": 6.7, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [6], "q": "Why do order errors matter for scoring memory?", "a": "Order errors are not random, and scoring only percent correct hides that people keep approximate position information.", "id": 494, "score": 6.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [7], "q": "Why are self-reports of mental imagery unreliable?", "a": "It is impossible to tell whether the images differ or only the descriptions, so researchers use tasks that require imagery and vary a critical part of the task.", "id": 495, "score": 8.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [7], "q": "What did Shepard and Metzler (1971) have people do?", "a": "They had people judge whether two block shapes were the same or mirror images, with one turned.", "id": 496, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [7], "q": "What did Shepard and Metzler (1971) find, and what does it suggest?", "a": "People mentally rotated one shape, and the larger the turn, the longer the response, at a constant rate. This suggests mental images are much like real images, and it influenced theories of mental representation.", "id": 497, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [8], "q": "What is the typical way people judge probability?", "a": "With heuristics that trade accuracy for speed, which are usually good enough but sometimes wrong. Tversky and Kahneman (1983) showed estimates often differ greatly from objective probability.", "id": 498, "score": 8.7, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [8], "q": "What is the conjunction fallacy?", "a": "Judging that A and B together are more likely than A alone or B alone, although a combination is never more likely than either part alone.", "id": 499, "score": 8.7, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [8], "q": "What did Shafir, Smith and Osherson (1990) find?", "a": "People sometimes rated a combination of professions or activities as more likely than one part, which points to heuristics rather than probability rules.", "id": 500, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [9], "q": "In the Wason Selection Task, which cards best test the rule If a card has a D on one side, it has a 3 on the other?", "a": "D and 7, since the 7 could falsify the rule. Most people choose D and 3, and the 3 can only confirm the rule.", "id": 501, "score": 8.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [9], "q": "How is the same logic easier in a familiar thematic rule?", "a": "With the rule If you borrow my car, you must fill up the gas tank, the correct cards are borrowed car and empty gas tank.", "id": 502, "score": 8.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [9], "q": "What did Wason and Shapiro (1971) compare?", "a": "Abstract and thematic rules. People test a rule well with relevant experience, and abstract rules force them to use logic alone.", "id": 503, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [10], "q": "What are framing effects?", "a": "They occur when the wording or context makes a big difference to a choice, even for otherwise equivalent situations. Kahneman and Tversky (1982) summarized many of them.", "id": 504, "score": 9.45, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [10], "q": "How does framing change a choice in classic Tversky and Kahneman research?", "a": "Gain wording typically leads to the sure option and loss wording to the gamble, so choices follow the framing and not the substance.", "id": 505, "score": 8.75, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [11], "q": "What is the Monty Hall 3 Door problem?", "a": "After you pick one of three doors, the host, who always plays fair this way, opens a no-prize door.", "id": 506, "score": 6.7, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [11], "q": "Should you stay or switch in the Monty Hall problem, and why?", "a": "You should switch, which wins about two-thirds of the time. Your first pick keeps its 1 in 3 chance, so the 2 in 3 held by the other two doors moves to the one remaining door.", "id": 507, "score": 6.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [11], "q": "What does the Monty Hall problem show about intuition?", "a": "It shows poor intuition about the probability of combinations of events, since many people think stay or switch makes no difference.", "id": 508, "score": 6.0, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [12], "q": "What are risky decisions?", "a": "Choices between a guaranteed outcome and a gamble, where the guaranteed outcome can be a gain or a loss, and the choice depends on how outcomes are framed and perceived.", "id": 509, "score": 7.075, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [12], "q": "What does prospect-theory research of Kahneman and Tversky show about risk?", "a": "People typically avoid risk with gains, taking the sure thing, and seek risk with losses, taking the gamble.", "id": 510, "score": 6.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [12], "q": "Why do decisions about risk not depend only on the odds?", "a": "They depend on whether outcomes are seen as gains or losses, not only on the objective odds.", "id": 511, "score": 6.375, "tier": "low"}, {"module": 14, "kind": "slide", "slides": [13], "q": "What did German and Defeyter (2000) test?", "a": "Whether young children get stuck on an object’s usual function, functional fixedness, using a box that was first shown as a container.", "id": 512, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [13], "q": "What did German and Defeyter (2000) find?", "a": "Older children, 6 and 7, were slower to use the box as a support after seeing it as a container, while 5-year-olds were not slowed and were even faster.", "id": 513, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [13], "q": "What does German and Defeyter’s (2000) result suggest about young children?", "a": "Younger children seem to have a more fluid idea of function, so one demonstrated use did not lock the object in.", "id": 514, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [14], "q": "What is the irrelevant speech effect in Leist and colleagues (2022)?", "a": "Speech to be ignored impairs serial recall, more for changing-state speech than for steady-state speech.", "id": 515, "score": 9.7, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [14], "q": "What did Leist and colleagues (2022) find about verbal and spatial items?", "a": "Speech hurt verbal recall but not spatial recall, in children and adults.", "id": 516, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [14], "q": "Which accounts does Leist and colleagues’ (2022) result fit better than attention-capture or changing-state accounts?", "a": "It fits phonological interference better, because the effect is specific to verbal material.", "id": 517, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [15], "q": "What is cognitive offloading in Morrison and Richmond (2020)?", "a": "Using actions like writing things down to reduce mental demands, as described by Risko and Gilbert (2016).", "id": 518, "score": 9.7, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [15], "q": "What did Morrison and Richmond (2020) find?", "a": "Offloading improved memory, especially at high loads, and people offloaded more as load grew.", "id": 519, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [15], "q": "Did memory ability predict who offloaded in Morrison and Richmond (2020)?", "a": "No. Memory ability did not predict who offloaded, so offloading may be a compensatory strategy across abilities.", "id": 520, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [16], "q": "What is the bat-and-ball problem (Frederick, 2005)?", "a": "A bat and ball cost $1.10 and the bat costs $1.00 more. The intuitive answer is 10 cents, and the correct answer is 5 cents.", "id": 521, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [16], "q": "What did Kahneman and Frederick (2002) and De Neys and colleagues (2013) say about the error?", "a": "Kahneman and Frederick called the error unconscious attribute substitution, and De Neys and colleagues found wrong reasoners were less confident than on a control version.", "id": 522, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [16], "q": "What did Hoover and Healy (2019) find?", "a": "Wrong reasoners mostly remembered the phrase more than, and because substitution cannot be confirmed as the cause of the error, they call it a sensitivity error.", "id": 523, "score": 9.0, "tier": "mid"}, {"module": 14, "kind": "slide", "slides": [17], "q": "What two effects did Giuliani and colleagues (2023) combine?", "a": "The framing effect, a sure option for gains and a risky option for losses, and the default effect, choosing the preselected option.", "id": 524, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [17], "q": "What did Giuliani and colleagues (2023) find about defaults and framing?", "a": "A risky default raised risk taking, a sure default did not raise risk aversion, and the two effects were additive.", "id": 525, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [17], "q": "What did the exploratory question show in Giuliani and colleagues (2023)?", "a": "In an exploratory question asked after the choice, the belief about the default’s origin went with following or rejecting it.", "id": 526, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [18], "q": "What do Albert, Chein and Steinberg (2013) argue about adolescent risk taking?", "a": "Adolescents reason about risk like adults in the lab, but the peer context is what raises risk taking.", "id": 527, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [18], "q": "What did Chein and colleagues (2011) find in their driving game?", "a": "Adolescents took more risks when watched by friends, with greater reward-region activity.", "id": 528, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "slide", "slides": [18], "q": "Did peers change cognitive control in Chein and colleagues (2011)?", "a": "No. Cognitive-control regions did not change with peers, so the authors concluded the effect worked mainly through reward circuitry.", "id": 529, "score": 9.375, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [1, 3], "q": "How do the phonological similarity effect and the Brown–Peterson task both concern short-term memory but different questions?", "a": "The similarity effect shows a speech-based code in the phonological loop, and the Brown–Peterson task asks how short-term memory loses information when rehearsal is blocked.", "id": 530, "score": 8.475, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [3], "q": "How do decay and interference differ as explanations of forgetting in the Brown–Peterson discussion?", "a": "Peterson and Peterson (1959) judged interference an unlikely cause because counting is so unlike remembering letters, and concluded that short-term memory loses information through decay unless it is rehearsed. This challenged the view, following McGeoch’s (1932) critique, that forgetting is due to interference, and Keppel and Underwood (1962) are cited for an alternative.", "id": 531, "score": 8.875, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [1, 2], "q": "How do the neighborhood size effect of Roodenrys et al. (2002) and the similarity effect each show about short-term recall?", "a": "Neighborhood size shows that long-term word knowledge helps short-term recall, so span is not a pure measure. The similarity effect shows the speech-based code used in short-term memory.", "id": 532, "score": 9.175, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [4, 5], "q": "How do the modality effect and Sperling’s (1960) work both bear on sensory memory?", "a": "The modality effect influenced ideas about a raw sensory back-up store, and partial report showed an iconic store briefly holds nearly all of a display.", "id": 533, "score": 9.8, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [6], "q": "How do the position error effect and percent-correct scoring relate?", "a": "Percent correct treats misplaced items as simply wrong, while errors landing in adjacent positions show people keep approximate position information.", "id": 534, "score": 6.5, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [7], "q": "How does the mental rotation result of Shepard and Metzler (1971) show that imagery can be studied without self-report?", "a": "In Shepard and Metzler (1971), response time rose at a constant rate with the angle of turn, so a measurable pattern supports image-like representations.", "id": 535, "score": 9.5, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [8, 10, 12], "q": "How do heuristics, the conjunction fallacy and framing share an idea about judgment?", "a": "Each shows judgments following a shortcut or wording and not objective probability or substance.", "id": 536, "score": 8.833, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [9, 11], "q": "How do the Wason Selection Task and the Monty Hall problem both show intuition going wrong?", "a": "People choose cards that confirm the rule and think switching makes no difference, because they miss what falsifies or how probability shifts.", "id": 537, "score": 8.4, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [9], "q": "Why are thematic rules easier than abstract rules in the Wason Selection Task of Wason and Shapiro (1971)?", "a": "With relevant experience people test a rule well, and abstract rules force them to use logic alone.", "id": 538, "score": 9.875, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [10, 12], "q": "How do framing in decisions and risky decisions relate?", "a": "Both show choices depending on whether outcomes are seen as gains or losses, with the sure option for gains and the gamble for losses.", "id": 539, "score": 8.775, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [10, 12, 17], "q": "How does Giuliani and colleagues (2023) extend the classic framing result?", "a": "It combined framing with defaults, and found a risky default raised risk taking while the two effects were additive.", "id": 540, "score": 9.883, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [13], "q": "How do German and Defeyter (2000) relate to functional fixedness and age?", "a": "Functional fixedness is getting stuck on an object’s usual function, and younger children showed immunity to it, so one demonstrated use did not lock the object in.", "id": 541, "score": 9.5, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [1, 14], "q": "How do Leist and colleagues (2022) and the phonological similarity effect both point to phonological processing?", "a": "Irrelevant speech hurt verbal but not spatial recall, and similar-sounding items are recalled worse, so both depend on speech-based processes.", "id": 542, "score": 9.175, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [15], "q": "How does cognitive offloading in Morrison and Richmond (2020) relate to memory load and ability?", "a": "Offloading helped most at high loads and increased as load grew, and ability did not predict who did it, so it may be a compensatory strategy.", "id": 543, "score": 9.5, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [8, 16], "q": "What do heuristics and the bat-and-ball problem both say about wrong answers that feel natural?", "a": "Heuristics trade accuracy for speed and are usually good enough but sometimes wrong. In the bat-and-ball problem the intuitive answer is 10 cents and the correct answer is 5 cents.", "id": 544, "score": 8.5, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [16], "q": "How do Hoover and Healy (2019) change the explanation of the bat-and-ball error?", "a": "They found wrong reasoners mostly remembered the phrase more than, and that attribute substitution cannot be confirmed as the cause, so they call it a sensitivity error.", "id": 545, "score": 9.5, "tier": "mid"}, {"module": 14, "kind": "relate", "slides": [18], "q": "How do Chein and colleagues (2011) and Albert, Chein and Steinberg (2013) fit together?", "a": "Adolescents reason like adults in the lab, but when watched by friends they take more risks with greater reward-region activity, and the authors concluded the effect worked mainly through reward circuitry and not changed cognitive control.", "id": 546, "score": 9.875, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [10, 17, 18], "q": "How do Giuliani and colleagues (2023) and Chein and colleagues (2011) show context shaping risky choice?", "a": "A risky default raised risk taking, framing flips sure and risky options, and peers raised adolescent risk taking, so context and not only reasoning changes risk.", "id": 547, "score": 10.15, "tier": "high"}, {"module": 14, "kind": "relate", "slides": [8, 9], "q": "How do the conjunction fallacy and the Wason Selection Task each show people departing from rules of probability or logic?", "a": "In the conjunction fallacy people judge A and B together as more likely than A alone, although a combination is never more likely than either part. In the Wason Selection Task most people choose D and 3, and the 3 can only confirm the rule, while D and 7 test it.", "id": 548, "score": 8.8, "tier": "low"}, {"module": 14, "kind": "relate", "slides": [3, 5], "q": "How do the Brown–Peterson task and Sperling’s (1960) partial report each use a delay or a distractor to study memory?", "a": "In the Brown–Peterson task a counting distractor blocks rehearsal and longer distraction gave worse recall. In Sperling’s (1960) partial report, delaying the cue made performance fall toward the usual limit, because the store is very short-lived.", "id": 549, "score": 9.875, "tier": "high"}];
